INSERT INTO public.deep_cases (id, market_id, day, slot, content, tags) VALUES
($ml$c3b7de5c-3905-5dbf-b369-02ade7bbac44$ml$::uuid, $ml$biotech$ml$, 1, 1, $ml${"id": "biotech-d1-c1", "title": "A target and a drug, both found by AI", "lessonTitle": "How a drug is discovered", "slot": 1, "type": "apply", "brief": {"headline": "Insilico Medicine used AI to pick a target for a lung scarring disease, a kinase called TNIK, and then to design a molecule against it. It reached a drug candidate in about 18 months.", "kicker": "Apply the discovery chain to an AI-found drug.", "fullText": "Idiopathic pulmonary fibrosis scars the lungs. Insilico Medicine's AI tools flagged TNIK, a kinase, as an important regulator of the disease. That was the target. Generative AI then designed molecules to block it, and the result was rentosertib, the candidate. The authors called it the first reported case of an AI platform finding both a disease target and a compound for it.\n\nInsilico took about 18 months to reach the candidate, and about 30 months from the start of target discovery to finishing early human testing. In a 12-week Phase 2a trial of 71 patients, published in Nature Medicine in June 2025, lung capacity in the 60 mg group rose by 98.4 mL on average, while it fell by 20.3 mL in the placebo group.\n\nThe steps were the ones from day 1: target, hits, lead, candidate. What changed was the tool doing the searching.", "sources": [{"url": "https://www.ajmc.com/view/ai-derived-therapy-for-ipf-shows-potential-in-phase-2a-trial", "label": "AJMC, AI-derived therapy for IPF shows potential in Phase 2a trial, Jun 2025"}, {"url": "https://www.cambridgemedchemconsulting.com/resources/stages.html", "label": "Cambridge MedChem, drug discovery stages"}]}, "evidence": {"kind": "buildChain", "prompt": "Put rentosertib's path in order.", "steps": ["AI flags TNIK as a driver of lung scarring", "AI designs molecules that block TNIK", "The best molecule becomes the candidate", "Early human tests check its safety", "A Phase 2a trial tests it in 71 patients"], "explanation": "Target first, then molecules, then a candidate, then people. AI sped up the search, but the order did not change."}, "numbers": {"kind": "numberSense", "prompt": "About how many months did Insilico take to reach its drug candidate?", "min": 0, "max": 60, "value": 18, "unit": "months", "explanation": "About 18 months to the candidate, and about 30 to finish early human testing."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're interviewing at an AI drug discovery company. They ask where AI did the work on rentosertib.", "prompt": "Which answer shows you know the stages?", "options": ["It ran the Phase 2a trial on its own", "It replaced the FDA's review of the drug", "It chose the target and designed the drug"], "correctIndex": 2, "consequences": ["Patients and doctors ran the trial; AI worked before it.", "The drug still faced FDA review before any human trial.", "Target choice and molecule design are the discovery stages AI covered."], "explanation": "Insilico used AI for target discovery and molecule design. Human trials and FDA review still followed."}, "proReasoning": "Name the stage a tool works on: target choice, hit finding or lead optimization. It shows you know the pipeline, not just the buzzword.", "commonMistake": "Talking about AI drug discovery without saying which stage it speeds up.", "mentalModel": "Place every tool on the chain."}, "invest": {"call": {"kind": "theCall", "situation": "A startup says AI found its drug in 18 months. You are judging what the company is worth.", "prompt": "What matters most for the risk ahead?", "options": ["The stage the drug has reached in trials", "How fast it got from target to candidate", "How advanced its AI platform sounds"], "correctIndex": 0, "consequences": ["A drug in early trials still faces years of testing.", "Speed saved time early, but the trials ahead carry the risk.", "Clever tools do not shorten the trials still to come."], "explanation": "Fast discovery saves time and money. The stage tells you how much risk is left before patients."}, "proReasoning": "Investors value a drug by its stage, not by how it was found. A fast discovery still faces the same trials as any other.", "commonMistake": "Paying for the speed of discovery as if it lowered the risk of trials.", "mentalModel": "The stage sets the risk."}, "build_startup": {"call": {"kind": "theCall", "situation": "You're building software for drug discovery. Insilico reached a candidate in about 18 months.", "prompt": "Which pitch to drug hunters is strongest?", "options": ["We have the largest AI model", "We shorten one named stage, with data", "We will make trials unnecessary"], "correctIndex": 1, "consequences": ["Size alone doesn't show you save a program any time.", "Time saved before trials is what buyers pay for.", "Every drug still needs human trials before approval."], "explanation": "Discovery takes years before the first trial. A tool that shortens one stage, and proves it, has a clear buyer."}, "proReasoning": "Founders pick one stage and measure the time they save there. Rentosertib gave the field a benchmark of about 18 months to a candidate.", "commonMistake": "Promising to fix the whole pipeline instead of one stage.", "mentalModel": "Shorten a stage, then prove it."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend says AI invented a drug for lung scarring, so it must be ready for pharmacies.", "prompt": "What's the fairest reply?", "options": ["Yes, AI drugs skip the usual tests", "No, AI cannot design molecules at all", "AI found it fast, but trials still decide"], "correctIndex": 2, "consequences": ["It went through human trials like any other drug.", "Insilico's AI did design the molecule before testing.", "It showed promise in a 71-patient trial, and more testing follows."], "explanation": "AI found the target and the candidate. Human trials, not the AI, decide whether it reaches patients."}, "proReasoning": "Separate how a drug was found from whether it works. Discovery is the start of the story, not the end.", "commonMistake": "Thinking a clever discovery means a finished medicine.", "mentalModel": "Found is not proven."}}}$ml$::jsonb, ARRAY['handwritten-v1']::text[]),
($ml$2e9dab98-2545-5f67-a606-cda8f364dbce$ml$::uuid, $ml$biotech$ml$, 1, 2, $ml${"id": "biotech-d1-c2", "title": "The clock before the clock", "lessonTitle": "How a drug is discovered", "slot": 2, "type": "connect", "brief": {"headline": "Approved drugs spent an average of 10.5 years between their first human trial and approval. Discovery, from target to candidate, happens before that clock even starts.", "kicker": "Connect two day 1 ideas: the target choice and the 10.5-year clock.", "fullText": "Day 1 opened with a number: in a study of 9,704 programs from 2011 to 2020, approved drugs took an average of 10.5 years from their first human trial to approval. Day 1 also showed what comes before that: choosing a target, screening for hits, optimizing a lead into a candidate, then filing an IND, which the FDA has 30 days to review.\n\nPut them together. The target is picked years before the first patient gets a dose, and every later year rests on that choice.", "sources": [{"url": "https://go.bio.org/rs/490-EHZ-999/images/ClinicalDevelopmentSuccessRates2011_2020.pdf", "label": "BIO, clinical development success rates 2011-2020"}, {"url": "https://www.cambridgemedchemconsulting.com/resources/stages.html", "label": "Cambridge MedChem, drug discovery stages"}, {"url": "https://www.everycrsreport.com/reports/RL30989.html", "label": "CRS, The US drug approval process"}]}, "evidence": {"kind": "multipleChoice", "prompt": "A team's IND has just cleared the FDA's 30-day review. What starts now?", "options": ["Screening molecules to find hits", "Human trials and the 10.5-year clock", "The search for a target to aim at"], "correctIndex": 1, "explanation": "The IND opens human trials. Target choice and screening came before it, in discovery."}, "numbers": {"kind": "numberSense", "prompt": "On average, how many years did approved drugs take from their first human trial to approval?", "min": 0, "max": 25, "value": 10.5, "unit": "years", "explanation": "10.5 years on average, and that is after discovery is already done."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You join a discovery team. Your manager asks how long your new target might take to reach patients.", "prompt": "What's the honest answer?", "options": ["Years of discovery, then about 10.5 more", "About 30 days, once the FDA reviews it", "A year or two if the chemistry goes well"], "correctIndex": 0, "consequences": ["Discovery comes first, and trials and review averaged 10.5 years.", "The 30 days is the IND review, the start of trials.", "Trials and review alone averaged 10.5 years."], "explanation": "A target sits at the very start. Discovery takes years, and trials and review averaged 10.5 more."}, "proReasoning": "People who know the timeline plan better and earn trust. Discovery years come before the 10.5-year average even starts.", "commonMistake": "Confusing the 30-day IND review with the time to approval.", "mentalModel": "Discovery first, then the long clock."}, "invest": {"call": {"kind": "theCall", "situation": "One biotech has a target and no molecule. Another just had its IND take effect.", "prompt": "Which has more years of risk ahead?", "options": ["They carry the same risk", "The one with only a target", "The one starting human trials"], "correctIndex": 1, "consequences": ["They sit at different stages, so the risk differs.", "It still needs hits, a lead and a candidate before any trial.", "It has finished discovery, though trials still lie ahead."], "explanation": "The target-only company has all of discovery ahead, then the same 10.5-year average stretch."}, "proReasoning": "Investors place each company on the pipeline before valuing it. The earlier the stage, the more years and risk remain.", "commonMistake": "Treating every preclinical company as equally far along.", "mentalModel": "Earlier stage, longer road."}, "build_startup": {"call": {"kind": "theCall", "situation": "You found a startup around a new target. Investors ask what your first milestone is.", "prompt": "Which milestone fits best?", "options": ["Start a Phase 3 trial next year", "Win approval within three years", "Find hits, then a lead worth an IND"], "correctIndex": 2, "consequences": ["Phase 3 needs a candidate, an IND and earlier trials first.", "Trials and review alone averaged 10.5 years.", "Discovery steps come before any human trial."], "explanation": "A target-stage startup must first find molecules that hit it and refine one into a candidate."}, "proReasoning": "Founders set milestones one stage ahead and fund each one. Promising approval from a bare target loses credibility.", "commonMistake": "Skipping discovery stages in the plan to sound faster.", "mentalModel": "Fund the next stage, not the last one."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why new medicines take so long to arrive.", "prompt": "What's the best short answer?", "options": ["Years of discovery, then about 10.5 in trials", "The FDA takes ten years to read each file", "Factories need a decade to make each pill"], "correctIndex": 0, "consequences": ["Discovery narrows the field, then trials and review take years.", "The FDA's IND review takes 30 days; trials take the time.", "Making the drug is not what takes the decade."], "explanation": "Discovery comes first. Then trials and review averaged 10.5 years for drugs that made it."}, "proReasoning": "Break a long wait into its stages. Most of the time goes into finding a molecule and proving it in people.", "commonMistake": "Blaming one slow step for a timeline built from many.", "mentalModel": "Long waits are made of stages."}}}$ml$::jsonb, ARRAY['handwritten-v1']::text[]),
($ml$524a9842-7dc6-54f0-8a78-22dffa83ef26$ml$::uuid, $ml$biotech$ml$, 1, 3, $ml${"id": "biotech-d1-c3", "title": "Which molecule moves on?", "lessonTitle": "How a drug is discovered", "slot": 3, "type": "decide", "brief": {"headline": "Discovery narrows the field: a target, then hits from screening, then a lead reshaped by chemists, then one candidate. Only the candidate goes into an IND.", "kicker": "Decide what stage each molecule has reached.", "fullText": "You run a small discovery team. Discovery starts with a target, a molecule in the body linked to a disease. Screening tests many molecules against it, and those that act on it are hits. Chemists then reshape promising hits for potency, safety and how well the body absorbs them. The best becomes the candidate.\n\nBefore any human trial, the sponsor files an IND with the FDA, which has 30 days to review it. Each stage drops most of what came before.", "sources": [{"url": "https://www.cambridgemedchemconsulting.com/resources/stages.html", "label": "Cambridge MedChem, drug discovery stages"}, {"url": "https://www.everycrsreport.com/reports/RL30989.html", "label": "CRS, The US drug approval process"}]}, "evidence": {"kind": "sortSignal", "prompt": "Which stage has each molecule reached?", "buckets": ["Hit", "Lead", "Candidate"], "items": [{"text": "Acted on the target in a first screen", "bucket": 0}, {"text": "One of many that showed activity in the test", "bucket": 0}, {"text": "Reshaped by chemists for potency and safety", "bucket": 1}, {"text": "Being tuned so the body absorbs it better", "bucket": 1}, {"text": "The single best compound, chosen for the IND", "bucket": 2}], "explanation": "Hits show activity, leads get refined, and one candidate goes forward to the IND."}, "numbers": {"kind": "numberSense", "prompt": "After filing an IND, how many days does the FDA have to review it?", "min": 0, "max": 90, "value": 30, "unit": "days", "explanation": "30 days. If the FDA does not object, human trials can begin."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "In a team meeting, a colleague calls a molecule from last week's screen \"our candidate.\"", "prompt": "How do you describe it correctly?", "options": ["It's the target we are aiming at", "It's a hit; it still needs lead work", "It's a candidate, ready for the IND"], "correctIndex": 1, "consequences": ["The target is what the molecule acts on, not the molecule.", "A fresh screen result is a hit until chemists refine it.", "A candidate comes after lead optimization, not a first screen."], "explanation": "A molecule that acted in a screen is a hit. Candidate is the last step before an IND."}, "proReasoning": "Biotech teams talk in stages, and using them precisely signals you belong. Hit, lead and candidate mean different amounts of work left.", "commonMistake": "Calling every promising molecule a candidate.", "mentalModel": "Use the stage names exactly."}, "invest": {"call": {"kind": "theCall", "situation": "A biotech says it has \"drug candidates\" in its deck. The fine print says they came from a recent screen.", "prompt": "How do you read it?", "options": ["They are ready for human trials", "The stage makes no difference", "They are hits, earlier than claimed"], "correctIndex": 2, "consequences": ["Hits need refining before an IND can be filed.", "Stage sets how much work and risk remain.", "Screen results still need lead work before any IND."], "explanation": "A screen produces hits. Candidates come only after lead optimization."}, "proReasoning": "Investors check stage labels against the work done. A hit called a candidate hides a year or more of chemistry.", "commonMistake": "Taking a company's stage labels at face value.", "mentalModel": "Check the label against the work."}, "build_startup": {"call": {"kind": "theCall", "situation": "You run a startup with 20 hits from a screen and money for one year of chemistry.", "prompt": "What's the smartest plan?", "options": ["Refine a few into leads, then pick one", "Take all 20 hits straight into an IND", "Run another screen to find more hits"], "correctIndex": 0, "consequences": ["Discovery narrows the field on purpose, toward one candidate.", "Hits are not ready; they need potency and safety work.", "You have hits; the next step is to refine them."], "explanation": "Discovery narrows: many hits, a few leads, one candidate. Spend the year on that funnel."}, "proReasoning": "Founders focus scarce money on the narrowing step. Twenty hits are a start; one strong candidate is a company.", "commonMistake": "Spreading money across every hit instead of narrowing.", "mentalModel": "Narrow the field toward one."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks what a drug \"candidate\" is, since it sounds like an election.", "prompt": "What's the best explanation?", "options": ["A drug already on pharmacy shelves", "The molecule picked to test in people", "Any chemical that gets tested in a lab"], "correctIndex": 1, "consequences": ["A candidate still has years of trials ahead.", "It won out over many hits and leads.", "Most lab chemicals never get past the hit stage."], "explanation": "A candidate is the best molecule left after screening and refining. It is the one that goes into an IND."}, "proReasoning": "Every medicine was once a candidate that beat many other molecules. The word marks the end of discovery and the start of trials.", "commonMistake": "Thinking a candidate is close to the pharmacy.", "mentalModel": "Candidate means chosen, not approved."}}}$ml$::jsonb, ARRAY['handwritten-v1']::text[]),
($ml$deada3ea-2360-579b-b122-2b5224b2af96$ml$::uuid, $ml$biotech$ml$, 2, 1, $ml${"id": "biotech-d2-c1", "title": "$500 million now, up to $12 billion later", "lessonTitle": "Who pays for a decade of R&D", "slot": 1, "type": "apply", "brief": {"headline": "In July 2025, GSK agreed to pay China's Hengrui Pharma $500 million up front for a COPD drug and options on 11 more programs. The deal could reach about $12 billion, if GSK takes every option and every milestone is hit.", "kicker": "Apply the payment stages to a 12-drug deal.", "fullText": "Hengrui's lead program is HRS-9821, a PDE3/4 inhibitor in clinical development as an add-on maintenance treatment for COPD. GSK paid $500 million up front, which included the license for that program. It also took an exclusive option on each of 11 more programs, for rights outside mainland China, Hong Kong, Macau and Taiwan. Hengrui runs each program through Phase 1.\n\nThe headline value, about $12 billion, assumes GSK takes up every option and every milestone is reached. Hengrui is also eligible for tiered royalties on sales.\n\nThrough the day 2 lens: the upfront is certain. The options, milestones and royalties all depend on the drugs working.", "sources": [{"url": "https://www.pharmexec.com/view/gsk-hengrui-pharma-reach-500-million-agreement", "label": "Pharmaceutical Executive, GSK and Hengrui Pharma reach $500 million agreement, Jul 2025"}, {"url": "https://www.pfizer.com/news/press-release/press-release-detail/pfizer-enters-exclusive-licensing-agreement-3sbio", "label": "Pfizer, 3SBio licensing deal"}]}, "evidence": {"kind": "sortSignal", "prompt": "Sort each part of the GSK deal: certain, or only if things work?", "buckets": ["Paid now", "Paid if it works"], "items": [{"text": "The $500 million upfront", "bucket": 0}, {"text": "The COPD license, bundled into the upfront", "bucket": 0}, {"text": "Payments on programs GSK opts into", "bucket": 1}, {"text": "Tiered royalties on sales", "bucket": 1}, {"text": "The full $12 billion headline", "bucket": 1}], "explanation": "Only the upfront was paid on signing. Everything else waits on options, results and sales."}, "numbers": {"kind": "numberSense", "prompt": "If the deal reaches $12 billion, what percent of it is the $500 million upfront?", "min": 0, "max": 20, "value": 4, "unit": "%", "explanation": "500 divided by 12,000 is about 4%. The other 96% has to be earned."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're interviewing for a business development role. They ask what GSK has truly committed to Hengrui.", "prompt": "Which answer is most precise?", "options": ["$500 million now; the rest hangs on options", "$12 billion, the value in the headlines", "Nothing until a drug wins approval"], "correctIndex": 0, "consequences": ["The upfront is certain; options, milestones and royalties are not.", "The $12 billion needs every option taken and every goal hit.", "The $500 million was paid on signing, before any approval."], "explanation": "Deal teams separate the guaranteed upfront from contingent value. Here, $500 million against a $12 billion headline."}, "proReasoning": "Deal people quote the upfront first and the headline second. It shows you know which money is real.", "commonMistake": "Repeating the headline value as if it were committed.", "mentalModel": "Upfront is real; the rest is earned."}, "invest": {"call": {"kind": "theCall", "situation": "You hold shares in a drugmaker that just signed a deal worth up to $12 billion, with $500 million up front.", "prompt": "How should you value the deal?", "options": ["Ignore the deal until a royalty arrives", "Count the upfront, weight the rest by odds", "Add the full $12 billion to its value now"], "correctIndex": 1, "consequences": ["The $500 million is cash in hand already.", "Most of the value depends on options and trial results.", "That assumes every option and every milestone, which is unlikely."], "explanation": "The upfront is certain. Each later payment is worth its size times its chance of being paid."}, "proReasoning": "Investors treat milestones as probabilities, not promises. A deal worth up to $12 billion may deliver far less.", "commonMistake": "Adding the headline value to the company as if it were cash.", "mentalModel": "Weight each payment by its odds."}, "build_startup": {"call": {"kind": "theCall", "situation": "You run a small biotech with several early programs. A big drugmaker offers a deal shaped like GSK and Hengrui's.", "prompt": "Which term protects you most if trials fail?", "options": ["A bigger total for milestones", "Higher royalty rates on sales", "A large upfront payment"], "correctIndex": 2, "consequences": ["Milestones pay only if the drugs hit their goals.", "Royalties need an approved drug that sells.", "The upfront is yours whatever the trials show."], "explanation": "When trials fail, contingent money never arrives. Only the upfront funds you regardless."}, "proReasoning": "Founders weigh upfront cash against headline size. A smaller deal with more cash now can be the safer one.", "commonMistake": "Chasing the biggest headline instead of the biggest certain payment.", "mentalModel": "Cash now protects; milestones reward."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend reads about a $12 billion GSK deal and asks if Hengrui just got $12 billion.", "prompt": "What do you tell them?", "options": ["It got $500 million; the rest is conditional", "Yes, the full amount was paid at signing", "No money changes hands until approval"], "correctIndex": 0, "consequences": ["The headline counts payments that may never come.", "Only $500 million was paid up front.", "GSK paid the $500 million on signing."], "explanation": "Deal headlines add up every possible payment. The cash paid today is usually a small slice."}, "proReasoning": "Read \"up to\" as a ceiling. The headline is the best case, not the payment.", "commonMistake": "Reading a deal headline as money paid.", "mentalModel": "\"Up to\" means best case."}}}$ml$::jsonb, ARRAY['handwritten-v1']::text[]),
($ml$ecdbd8a1-d392-5836-8ceb-c88fffefdc23$ml$::uuid, $ml$biotech$ml$, 2, 2, $ml${"id": "biotech-d2-c2", "title": "Why the money waits for proof", "lessonTitle": "Who pays for a decade of R&D", "slot": 2, "type": "connect", "brief": {"headline": "Counting failed attempts, one study put the median cost of a new drug at $985 million. Approved drugs spent 10.5 years on average in trials and review. That is why deals pay in stages.", "kicker": "Connect day 1 and day 2: a long road explains staged deals.", "fullText": "On day 1 you saw the timeline: approved drugs averaged 10.5 years from first human trial to approval. On day 2 you saw the cost: a 2020 study put the median at $985 million per new drug, and the mean at $1.3 billion, counting failed attempts.\n\nPut them together. A buyer licensing a drug in trials faces years of spending and a real chance of failure. So deals pay a little up front, like Pfizer's $1.25 billion for SSGJ-707, and much more only if the drug works: up to $4.8 billion in milestones, plus royalties on sales.", "sources": [{"url": "https://go.bio.org/rs/490-EHZ-999/images/ClinicalDevelopmentSuccessRates2011_2020.pdf", "label": "BIO, clinical development success rates 2011-2020"}, {"url": "https://www.lshtm.ac.uk/newsevents/news/2020/average-cost-developing-new-drug-could-be-15-billion-less-pharmaceutical", "label": "LSHTM on Wouters et al., JAMA 2020"}, {"url": "https://www.pfizer.com/news/press-release/press-release-detail/pfizer-enters-exclusive-licensing-agreement-3sbio", "label": "Pfizer, 3SBio licensing deal"}]}, "evidence": {"kind": "spotFake", "prompt": "One of these is false. Tap it.", "statements": ["The $985 million median counts failed attempts.", "Approved drugs averaged 10.5 years from first trial to approval.", "Most of a licensing deal is usually paid on signing."], "fakeIndex": 2, "explanation": "Pfizer paid $1.25 billion on signing against up to $4.8 billion in milestones. Most of the money waits for results."}, "numbers": {"kind": "numberSense", "prompt": "The 2020 study put the mean cost of developing a new drug at how many billion dollars?", "min": 0, "max": 3, "value": 1.3, "unit": "B", "explanation": "$1.3 billion on average, and $985 million at the median, once failures are counted."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're in R&D finance. A manager asks why the company's cost per approved drug looks so high.", "prompt": "What's the best explanation?", "options": ["The FDA charges high fees per drug", "It includes the programs that failed", "Factories are costly to run"], "correctIndex": 1, "consequences": ["Fees are small next to a decade of trials.", "Counting failures, the median was $985 million per new drug.", "Making the drug is a small part of R&D cost."], "explanation": "The cost of an approved drug carries the failures that came before it."}, "proReasoning": "Finance teams spread the cost of failures over the winners. That is why one approval can carry a near $1 billion price tag.", "commonMistake": "Counting only the cost of the drug that succeeded.", "mentalModel": "Winners carry the cost of losers."}, "invest": {"call": {"kind": "theCall", "situation": "A biotech licenses out a drug just entering trials. The buyer offers a small upfront and big milestones.", "prompt": "Why is that structure common?", "options": ["Buyers are short of cash", "Drugs in trials are usually approved quickly", "Years of trials lie ahead, so pay waits for proof"], "correctIndex": 2, "consequences": ["Big drugmakers stage payments by choice, to match the risk.", "Approved drugs averaged 10.5 years from the first trial.", "With about 10.5 years ahead, buyers pay as risk falls."], "explanation": "The further a drug is from approval, the more of the price waits on results."}, "proReasoning": "Investors read deal structure as a risk signal. A small upfront with large milestones means the buyer sees a long road ahead.", "commonMistake": "Reading a small upfront as a lack of interest.", "mentalModel": "Long roads mean staged pay."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup has a candidate about to start trials. You need to fund the next few years.", "prompt": "What should your plan assume?", "options": ["Years of trials before most deal money arrives", "Milestones will pay out within months", "A deal will cover the whole decade up front"], "correctIndex": 0, "consequences": ["Milestones follow results, and results take years.", "Milestones wait for trial results and approvals.", "Upfronts are a fraction of the total, even Pfizer's."], "explanation": "Plan cash for the long road. Deal money arrives in stages, as the drug proves itself."}, "proReasoning": "Founders plan runway to the next result, not to the deal headline. Milestones are earned, not scheduled.", "commonMistake": "Budgeting milestone money before the trials that trigger it.", "mentalModel": "Plan cash to the next result."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why drug companies pay billions for drugs that might fail.", "prompt": "What's the key idea?", "options": ["The seller refunds the money if it fails", "They pay in stages, more as it proves itself", "Every drug they buy ends up approved anyway"], "correctIndex": 1, "consequences": ["No refund; the upfront is kept whatever happens.", "Some cash up front, the rest only if it works.", "Many drugs in trials fail; that is why payment is staged."], "explanation": "Most of the headline is paid only if the drug works. The buyer limits its loss if it fails."}, "proReasoning": "Big numbers in biotech deals are mostly conditional. The structure lets buyers bet on many drugs without paying full price for failures.", "commonMistake": "Assuming the headline price is paid for every drug.", "mentalModel": "Pay more as the risk falls."}}}$ml$::jsonb, ARRAY['handwritten-v1']::text[]),
($ml$d16d9cc1-6fd1-56b4-b26a-4484ed80bd7c$ml$::uuid, $ml$biotech$ml$, 2, 3, $ml${"id": "biotech-d2-c3", "title": "When does 3SBio get paid?", "lessonTitle": "Who pays for a decade of R&D", "slot": 3, "type": "decide", "brief": {"headline": "Pfizer paid 3SBio $1.25 billion up front for SSGJ-707 and bought $100 million of its shares. Up to $4.8 billion more in milestones, and royalties on sales, depend on the drug working.", "kicker": "Decide what to count on, and when.", "fullText": "In May 2025, Pfizer licensed SSGJ-707, a bispecific antibody targeting PD-1 and VEGF, from China's 3SBio. It took worldwide rights outside China. The drug was in trials for lung, colorectal and gynecological cancers.\n\nPfizer agreed to pay $1.25 billion up front, up to $4.8 billion in development, regulatory and commercial milestones, and tiered double-digit royalties on sales if the drug is approved. It also bought $100 million of 3SBio shares.\n\nYou run planning at 3SBio. Each payment arrives at a different time, and only some are certain.", "sources": [{"url": "https://www.pfizer.com/news/press-release/press-release-detail/pfizer-enters-exclusive-licensing-agreement-3sbio", "label": "Pfizer, 3SBio licensing deal"}]}, "evidence": {"kind": "buildChain", "prompt": "Put the payments to 3SBio in the order they could arrive.", "steps": ["$1.25 billion upfront on signing", "Milestones for trial results", "A milestone for regulatory approval", "Royalties as the drug sells"], "explanation": "Cash on signing, then milestones as trials and approval succeed, then royalties once it sells."}, "numbers": {"kind": "numberSense", "prompt": "Upfront is $1.25 billion of a possible $6.05 billion before royalties. About what percent is that?", "min": 0, "max": 100, "value": 21, "unit": "%", "explanation": "1.25 divided by 6.05 is about 21%. Nearly four fifths of the headline depends on results."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You join 3SBio's finance team after the Pfizer deal. You must forecast next year's cash from it.", "prompt": "What do you count on?", "options": ["The full $4.8 billion in milestones", "Royalties from next year's sales", "The upfront and the share purchase"], "correctIndex": 2, "consequences": ["Milestones need trial results and approval first.", "Royalties start only after approval and launch.", "Only money paid on signing is certain."], "explanation": "Forecast the certain money as cash. Treat milestones and royalties as possibilities."}, "proReasoning": "Finance teams book certain cash and model the rest as scenarios. Mixing the two is how forecasts go wrong.", "commonMistake": "Putting milestones in the forecast as if they were scheduled.", "mentalModel": "Book the certain; model the rest."}, "invest": {"call": {"kind": "theCall", "situation": "Two licensing deals have the same headline value. One pays far more of it up front.", "prompt": "Which is worth more today?", "options": ["The one with more paid up front", "The one with more in milestones", "Neither, since the totals match"], "correctIndex": 0, "consequences": ["Cash now beats cash that depends on results.", "Milestones may never be paid if trials fail.", "The totals match, but the certain part differs."], "explanation": "Equal headlines can hide very different certain value. Upfront cash carries no trial risk."}, "proReasoning": "Investors compare deals by the certain part first. The headline is the best case for both.", "commonMistake": "Ranking deals by headline value.", "mentalModel": "Same headline, different risk."}, "build_startup": {"call": {"kind": "theCall", "situation": "You run a biotech negotiating a deal for your lead drug. The buyer offers higher royalties for a smaller upfront.", "prompt": "When does that trade make sense?", "options": ["Always, since royalties have no limit", "When you have cash to reach the next results", "When you need cash to survive this year"], "correctIndex": 1, "consequences": ["Royalties are zero if the drug never sells.", "You can afford to wait for royalties that need approval.", "Royalties pay only after approval, years away."], "explanation": "Royalties reward you only after approval. Take them over cash only if you can fund the wait."}, "proReasoning": "Founders trade upfront for royalties only when the runway allows it. Survival comes before upside.", "commonMistake": "Taking a bigger royalty you may not live to collect.", "mentalModel": "Survive first, then share the upside."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend sees \"up to $4.8 billion in milestones\" and asks what \"up to\" means.", "prompt": "What's the best explanation?", "options": ["The minimum Pfizer has promised to pay", "An estimate of the drug's yearly sales", "The most it pays, if every goal is hit"], "correctIndex": 2, "consequences": ["Milestones are a ceiling, not a floor.", "Sales are covered by royalties, a separate term.", "Each milestone pays only if its goal is reached."], "explanation": "Milestones are paid one by one as goals are met. \"Up to\" is the total if all of them are."}, "proReasoning": "Translate deal language into conditions. Each milestone is a bet on one result.", "commonMistake": "Reading \"up to\" as a promise.", "mentalModel": "Milestones are conditions with prices."}}}$ml$::jsonb, ARRAY['handwritten-v1']::text[]),
($ml$41c59aa7-2a00-5f2a-a11b-5bbd63570378$ml$::uuid, $ml$biotech$ml$, 3, 1, $ml${"id": "biotech-d3-c1", "title": "Stelara's first year of competition", "lessonTitle": "Who holds the power: patents", "slot": 1, "type": "apply", "brief": {"headline": "The first US biosimilar of Stelara, J&J's immune disease drug, launched on January 1, 2025. In the fourth quarter, Stelara's sales fell 47.7% from a year earlier, to $1.23 billion.", "kicker": "Apply the patent clock to Stelara's 2025.", "fullText": "Stelara is a biologic drug. Copies of biologics are called biosimilars. Stelara's key patent expired in September 2023, but a settlement with J&J delayed Amgen's biosimilar, Wezlana, until January 1, 2025. Six more were expected that year, and by mid-2025 eight had launched in the US. Most were listed 80% to 90% below Stelara's price.\n\nIn the fourth quarter of 2025, Stelara's sales fell 47.7% to $1.23 billion. US sales fell 54.9%. It is the day 3 patent cliff: when protection ends, cheaper copies arrive and take the market.", "sources": [{"url": "https://www.centerforbiosimilars.com/view/welcome-wezlana-the-first-stelara-biosimilar-to-launch-in-the-us", "label": "Center for Biosimilars, Wezlana, the first Stelara biosimilar to launch in the US, Jan 2025"}, {"url": "https://trial.medpath.com/news/6b279b89e55bd41f/stelara-biosimilars-capture-market-share-as-j-j-s-blockbuster-drug-faces-33-7-sales-decline", "label": "MedPath, Stelara biosimilars capture market share, Jul 2025"}, {"url": "https://finviz.com/news/282631/jj-stock-down-despite-q4-earnings-beat-oncology-drugs-drive-sales", "label": "Zacks via Finviz, J&J fourth quarter 2025 results, Jan 2026"}]}, "evidence": {"kind": "multipleChoice", "prompt": "Stelara's key patent expired in September 2023. Why did the first US copy wait until 2025?", "options": ["The FDA banned copies for two years", "A settlement with J&J delayed it", "No company had tried to copy it"], "correctIndex": 1, "explanation": "Amgen's settlement with J&J moved Wezlana's launch from late 2023 to January 1, 2025."}, "numbers": {"kind": "numberSense", "prompt": "By about what percent did Stelara's US sales fall in the fourth quarter of 2025?", "min": 0, "max": 100, "value": 55, "unit": "%", "explanation": "About 55% in the US, and 47.7% worldwide, in the first year of biosimilars."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're interviewing at J&J in 2026. At the end, they ask if you have questions.", "prompt": "Which question shows you understand the business?", "options": ["Will the FDA ban the Stelara biosimilars?", "What will replace Stelara's lost sales?", "How many people work on the Stelara team?"], "correctIndex": 1, "consequences": ["The biosimilars are approved and legal to sell.", "It shows you know the patent clock and what comes next.", "Headcount says little about the business problem."], "explanation": "When a top drug loses protection, the question is what replaces it. That is the strategic issue."}, "proReasoning": "Ask when the top drugs lose protection and what will replace them. Interviewers notice candidates who think about the patent clock.", "commonMistake": "Treating a patent cliff as a legal issue rather than a business one.", "mentalModel": "Ask what replaces the lost sales."}, "invest": {"call": {"kind": "theCall", "situation": "A drugmaker's top biologic loses protection next year. You're forecasting its sales.", "prompt": "What does Stelara's 2025 suggest?", "options": ["Expect sales to hold; biologics are hard to copy", "Expect a small dip of a few percent", "Expect a steep fall once copies launch"], "correctIndex": 2, "consequences": ["Eight Stelara biosimilars launched in the US within months.", "Stelara fell far more than a few percent.", "Stelara's fourth-quarter sales fell 47.7% in year one."], "explanation": "With many cheap copies, sales of the original can halve within a year."}, "proReasoning": "Investors map each top drug's loss of exclusivity and model a steep drop. Stelara showed how fast it can come.", "commonMistake": "Assuming a biologic is safe from copies.", "mentalModel": "Map the cliff, model the drop."}, "build_startup": {"call": {"kind": "theCall", "situation": "You run a biotech with an immune disease drug in Phase 2. J&J is losing Stelara sales to copies.", "prompt": "How does that change your position?", "options": ["J&J may pay more to fill the gap", "J&J will stop buying immune drugs", "It doesn't matter at Phase 2"], "correctIndex": 0, "consequences": ["A drugmaker losing sales needs new drugs, which helps you bargain.", "Losing a drug makes replacements more needed, not less.", "Buyers look at drugs in trials when sales are falling."], "explanation": "A patent cliff creates a buyer with a deadline. That gives smaller biotechs bargaining power."}, "proReasoning": "Founders watch big drugmakers' cliffs to find motivated buyers. A deadline on their side is power on yours.", "commonMistake": "Ignoring who is about to lose sales in your field.", "mentalModel": "Cliffs create buyers."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why cheaper versions of Stelara suddenly appeared in 2025.", "prompt": "What's the best answer?", "options": ["The FDA forced J&J to share its formula", "Its protection ended, so rivals copied it", "J&J chose to cut its own price by 90%"], "correctIndex": 1, "consequences": ["Rivals developed their own versions after protection ended.", "The key patent ended, and a settlement set the 2025 launch.", "The cheap versions came from rivals, not J&J."], "explanation": "When a drug's protection ends, rivals can sell copies, usually far cheaper."}, "proReasoning": "Drug prices often fall on a schedule set years earlier by patents. Ask when protection ends.", "commonMistake": "Thinking price drops come from the original maker's generosity.", "mentalModel": "Protection ends, copies arrive."}}}$ml$::jsonb, ARRAY['handwritten-v1']::text[]),
($ml$134f28a1-5b21-5b67-9af5-8dc7251f1d66$ml$::uuid, $ml$biotech$ml$, 3, 2, $ml${"id": "biotech-d3-c2", "title": "Two weeks of Keytruda", "lessonTitle": "Who holds the power: patents", "slot": 2, "type": "connect", "brief": {"headline": "Keytruda sold $31.7 billion in 2025, about 55% of Merck's drug sales, and its IV form loses exclusivity in 2028. Against that, Pfizer's $1.25 billion upfront for one drug looks small.", "kicker": "Connect day 2 and day 3: a patent deadline sets what drugs are worth.", "fullText": "On day 3 you saw Keytruda: $31.7 billion in 2025 sales, up 7%, about 55% of Merck's pharmaceutical sales, with its IV form set to lose exclusivity in 2028. On day 2 you saw Pfizer pay $1.25 billion up front for an experimental cancer drug.\n\nPut them together. A drugmaker facing a cliff needs new drugs fast. Next to the sales at stake, even a billion-dollar upfront is a small price. That deadline is what gives the sellers of new drugs their bargaining power.", "sources": [{"url": "https://www.zacks.com/stock/news/2878133/mercks-keytruda-drives-its-2025-revenue-surge-whats-ahead", "label": "Zacks on Keytruda 2025 sales"}, {"url": "https://www.pfizer.com/news/press-release/press-release-detail/pfizer-enters-exclusive-licensing-agreement-3sbio", "label": "Pfizer, 3SBio licensing deal"}]}, "evidence": {"kind": "spotFake", "prompt": "One of these is false. Tap it.", "statements": ["Keytruda's IV form is set to lose exclusivity in 2028.", "Keytruda made about 55% of Merck's drug sales in 2025.", "Pfizer paid all of its 3SBio deal on signing."], "fakeIndex": 2, "explanation": "Pfizer paid $1.25 billion up front. Up to $4.8 billion more depends on milestones."}, "numbers": {"kind": "numberSense", "prompt": "At $31.7 billion a year, about how many days of Keytruda sales equal Pfizer's $1.25 billion upfront?", "min": 0, "max": 60, "value": 14, "unit": "days", "explanation": "1.25 divided by 31.7, times 365, is about 14 days. A replacement is cheap next to the sales at risk."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're in business development at a drugmaker whose top drug loses exclusivity in three years.", "prompt": "What's your priority?", "options": ["Wait until the cliff arrives, then act", "Cut the price of the top drug now", "License drugs to replace those sales"], "correctIndex": 2, "consequences": ["Waiting leaves no time for new drugs to arrive.", "A price cut speeds the decline without replacing it.", "New drugs take years to reach market, so buying early fills the gap."], "explanation": "Licensing early is how drugmakers fill a coming gap. The deadline drives the deal pace."}, "proReasoning": "Business development teams work backward from the cliff date. The closer it gets, the more they will pay.", "commonMistake": "Treating the cliff as a problem for later.", "mentalModel": "Work backward from the cliff."}, "invest": {"call": {"kind": "theCall", "situation": "Two biotechs have similar Phase 2 drugs. One works in a field whose top seller loses protection soon.", "prompt": "Which likely gets the better deal terms?", "options": ["The one near the coming patent cliff", "The one in a field with no cliff", "Both the same, since the data match"], "correctIndex": 0, "consequences": ["A buyer racing a deadline pays more for a replacement.", "Fewer urgent buyers usually means weaker terms.", "Buyer urgency changes terms even when data match."], "explanation": "A cliff creates urgent buyers. Urgency raises what a seller can ask for."}, "proReasoning": "Investors map big drugmakers' cliffs to see which small biotechs have motivated buyers. Timing shapes price.", "commonMistake": "Valuing a drug only on its data, ignoring who needs it.", "mentalModel": "Urgent buyers pay more."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your drug could compete in a $30 billion market whose leader loses exclusivity in 2028.", "prompt": "When should you look for a partner?", "options": ["Never; take it alone through approval", "Before 2028, while buyers race the clock", "After 2028, once the copies have arrived"], "correctIndex": 1, "consequences": ["Going alone means funding years of trials yourself.", "Your bargaining power peaks while the deadline looms.", "After the cliff, the buyer's urgency has passed."], "explanation": "The seller's power is highest while the buyer still has time to use the drug before the cliff."}, "proReasoning": "Founders time deal talks to the buyer's deadline. The same drug can be worth more two years before a cliff.", "commonMistake": "Negotiating on your timeline instead of the buyer's.", "mentalModel": "Sell into the buyer's deadline."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why big drugmakers pay so much for drugs still in trials.", "prompt": "What's the best explanation?", "options": ["Drugs in trials are cheaper to sell", "The seller refunds them if trials fail", "Their top sellers will lose protection"], "correctIndex": 2, "consequences": ["A drug still in trials can't be sold at all.", "Upfront payments are kept whatever happens.", "When protection ends, they need new drugs to replace lost sales."], "explanation": "Patent clocks run out on big sellers. Buying drugs in trials is how drugmakers refill the pipeline."}, "proReasoning": "Behind many biotech deals is a patent date. Find the cliff and the deal makes sense.", "commonMistake": "Thinking big deals are just about one exciting drug.", "mentalModel": "Look for the cliff behind the deal."}}}$ml$::jsonb, ARRAY['handwritten-v1']::text[]),
($ml$a3394cfb-b16c-5afa-9366-1461384a3457$ml$::uuid, $ml$biotech$ml$, 3, 3, $ml${"id": "biotech-d3-c3", "title": "Patent or exclusivity?", "lessonTitle": "Who holds the power: patents", "slot": 3, "type": "decide", "brief": {"headline": "A US patent lasts 20 years from filing. Separately, the FDA grants exclusivity on approval: 5 years for a new chemical entity, 7 for an orphan drug. When protection ends, generics arrive.", "kicker": "Decide which protection is doing the work.", "fullText": "Two kinds of protection shape a drug's life. Patents are granted by the US Patent and Trademark Office and can come anywhere along development. A US patent lasts 20 years from the day the application is filed. Exclusivity is granted by the FDA when a drug is approved: 5 years for a new chemical entity and 7 for an orphan drug. The two may run at the same time, but need not.\n\nWhen protection ends, generics arrive. They do not repeat the original clinical trials, so they cost less. With five competitors, prices can drop nearly 85%.", "sources": [{"url": "https://www.fda.gov/drugs/development-approval-process-drugs/frequently-asked-questions-patents-and-exclusivity", "label": "FDA, patents and exclusivity FAQ"}, {"url": "https://www.fda.gov/industry/fda-basics-industry/how-can-i-better-understand-patents-and-exclusivity", "label": "FDA, understanding patents and exclusivity"}, {"url": "https://www.fda.gov/drugs/generic-drugs/generic-drug-facts", "label": "FDA, generic drug facts"}]}, "evidence": {"kind": "sortSignal", "prompt": "Which kind of protection is each one?", "buckets": ["Patent", "FDA exclusivity"], "items": [{"text": "Lasts 20 years from the filing date", "bucket": 0}, {"text": "Granted by the Patent and Trademark Office", "bucket": 0}, {"text": "Can come at any point during development", "bucket": 0}, {"text": "Granted when the drug is approved", "bucket": 1}, {"text": "5 years for a new chemical entity", "bucket": 1}, {"text": "7 years for an orphan drug", "bucket": 1}], "explanation": "Patents come from the patent office and run from filing. Exclusivity comes from the FDA and starts at approval."}, "numbers": {"kind": "numberSense", "prompt": "A patent lasts 20 years from filing. If the drug is approved 12 years after filing, how many patent years are left?", "min": 0, "max": 20, "value": 8, "unit": "years", "explanation": "20 minus 12 leaves 8. Development eats much of the patent before the first sale."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're new in regulatory affairs. A drug for a rare disease may qualify for orphan status.", "prompt": "What does orphan status add?", "options": ["Seven years of exclusivity from the FDA", "A fresh 20-year patent on the drug", "An exemption from all clinical trials"], "correctIndex": 0, "consequences": ["Orphan drugs get 7 years, against 5 for a new chemical entity.", "Patents come from the patent office, not orphan status.", "Orphan drugs still need trials and approval."], "explanation": "Orphan status brings 7 years of exclusivity from the FDA, on top of whatever patents exist."}, "proReasoning": "Regulatory teams know which protections a drug can earn. Getting the source and length right is basic fluency.", "commonMistake": "Mixing up patents and FDA exclusivity.", "mentalModel": "Patent office for patents, FDA for exclusivity."}, "invest": {"call": {"kind": "theCall", "situation": "A drug is approved 12 years after its main patent was filed. Management says it has \"20 years of protection.\"", "prompt": "How do you read that?", "options": ["More, since approval resets the patent", "Far less: the patent clock started at filing", "Accurate, since patents last 20 years"], "correctIndex": 1, "consequences": ["Approval brings exclusivity, but no new patent term.", "About 8 patent years remain, so check exclusivity too.", "The 20 years run from filing, not from approval."], "explanation": "The patent clock started at filing. What matters is how much protection is left after approval."}, "proReasoning": "Investors count protection from today, not from filing. Remaining years drive a drug's value.", "commonMistake": "Taking the full patent term as the selling window.", "mentalModel": "Count the years left, not the term."}, "build_startup": {"call": {"kind": "theCall", "situation": "You're choosing a first disease for your new drug: a common one or a rare one.", "prompt": "Which protection fact bears on the choice?", "options": ["Drugs for rare diseases get no patents", "Common disease drugs skip FDA review", "Orphan drugs get 7 years of exclusivity"], "correctIndex": 2, "consequences": ["Patents are available for drugs of any kind.", "Every new drug goes through FDA review.", "That is two more years than a new chemical entity gets."], "explanation": "A rare disease drug can earn 7 years of FDA exclusivity, against 5 for a new chemical entity."}, "proReasoning": "Founders weigh protection along with market size. A longer exclusive window can make a smaller market worth more.", "commonMistake": "Choosing a disease without checking what protection it brings.", "mentalModel": "Protection is part of the market."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why their generic pill costs a fraction of the brand.", "prompt": "What's the main reason?", "options": ["Generics skip the original trials", "Generics use weaker ingredients", "The government pays the difference"], "correctIndex": 0, "consequences": ["With five competitors, prices can drop nearly 85%.", "Generics must match the brand; cost comes from skipped trials.", "Competition among copies drives the price down."], "explanation": "Generics do not repeat the original trials, and competing copies push prices down."}, "proReasoning": "The cost of a drug is mostly the cost of proving it. Copies that skip that step can sell far cheaper.", "commonMistake": "Assuming cheaper means lower quality.", "mentalModel": "Skip the trials, cut the price."}}}$ml$::jsonb, ARRAY['handwritten-v1']::text[]),
($ml$640d5786-47d0-5c55-8737-09ec257ffa1b$ml$::uuid, $ml$biotech$ml$, 4, 1, $ml${"id": "biotech-d4-c1", "title": "A lottery ticket called evoke", "lessonTitle": "The odds every drug faces", "slot": 1, "type": "apply", "brief": {"headline": "In November 2025, two Phase 3 trials of semaglutide in Alzheimer's disease failed. UBS had put the chance of success at only 10%, yet Novo Nordisk's shares still fell 8.3% that day.", "kicker": "Apply payoff times odds to Novo's Alzheimer's bet.", "fullText": "Semaglutide is the ingredient behind Novo Nordisk's diabetes and obesity drugs. The evoke and evoke+ trials tested a daily oral form in 3,808 adults aged 55 to 85 with mild cognitive impairment or mild Alzheimer's dementia. After 104 weeks, it did not slow disease progression compared with placebo, though several Alzheimer's-related biomarkers improved.\n\nNobody called it a sure thing. UBS estimated a 10% chance of success, a senior Novo executive had called the trials a lottery ticket, and Novo's chief scientific officer spoke of exploring the drug's potential despite a low likelihood of success. On November 24, 2025, the shares fell 8.32% in Copenhagen.\n\nThe day 4 rule: a drug's value is its payoff times its odds. A low-odds bet still carries value until the result arrives.", "sources": [{"url": "https://www.hl.co.uk/shares/stock-market-news/company--news/novo-nordisk-shares-fall-on-failure-of-two-big-alzheimers-studies", "label": "Hargreaves Lansdown, Novo Nordisk shares fall on failure of two big Alzheimer's studies, Nov 2025"}, {"url": "https://www.hcplive.com/view/semaglutide-fails-to-demonstrate-reduction-in-alzheimer-s-progression-versus-placebo", "label": "HCPLive, Semaglutide fails to show reduction in Alzheimer's progression, Nov 2025"}, {"url": "https://go.bio.org/rs/490-EHZ-999/images/ClinicalDevelopmentSuccessRates2011_2020.pdf", "label": "BIO, clinical development success rates 2011-2020"}]}, "evidence": {"kind": "multipleChoice", "prompt": "UBS gave the trials a 10% chance. Why did the shares still fall when they failed?", "options": ["Some value for success was priced in", "Investors were sure it would work", "The drug turned out to be unsafe"], "correctIndex": 0, "explanation": "A 10% chance at a big payoff is worth something. When the trials failed, that value went to zero."}, "numbers": {"kind": "numberSense", "prompt": "What chance of success did UBS give the evoke trials, in percent?", "min": 0, "max": 50, "value": 10, "unit": "%", "explanation": "10%. Low odds, but a huge payoff, so the bet still carried value."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're interviewing for an R&D strategy team days after evoke failed. They ask if running it was a mistake.", "prompt": "What's the strongest answer?", "options": ["Yes, any trial that fails was a mistake", "No, because Phase 3 trials rarely fail", "Not if the payoff justified 10% odds"], "correctIndex": 2, "consequences": ["Most trials fail, so the outcome alone cannot judge the choice.", "Drugs that reach Phase 3 still fail often, as evoke shows.", "Judging a bet by its odds and payoff is how portfolios run."], "explanation": "A good bet can lose. Judge the decision by the odds and payoff known at the start."}, "proReasoning": "Strategy teams judge a trial by the odds and payoff at the start, not only by the result. Saying so shows portfolio thinking.", "commonMistake": "Judging a decision only by how it turned out.", "mentalModel": "Judge the bet, not just the outcome."}, "invest": {"call": {"kind": "theCall", "situation": "A big drugmaker is running a Phase 3 trial that analysts give a 10% chance. Results are a year away.", "prompt": "How should you value the trial today?", "options": ["Its payoff times a 10% chance", "Its full payoff, since it reached Phase 3", "Zero, since 10% is too low to count"], "correctIndex": 0, "consequences": ["That is the risk-adjusted value the market carries.", "Reaching Phase 3 does not make success likely here.", "A 10% chance at a big payoff is worth something."], "explanation": "Multiply the payoff by the odds. That value is what disappears if the trial fails."}, "proReasoning": "Investors risk-adjust every program and expect the stock to move by the value at stake. Even a long shot can move the price.", "commonMistake": "Treating a long shot as either free or certain.", "mentalModel": "Value equals payoff times odds."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup has one drug. A trial with odds near 10% would use all your cash.", "prompt": "What does evoke teach about that bet?", "options": ["Skip any trial that might fail", "Size the bet to what failure would cost you", "Copy Novo, since big trials are worth it"], "correctIndex": 1, "consequences": ["Every trial might fail, since most drugs do.", "A failure that ends the company is a different bet from Novo's.", "Novo had other drugs to fall back on; you do not."], "explanation": "Novo could take a lottery ticket because the loss would not sink it. A one-drug startup must weigh survival."}, "proReasoning": "Founders size each bet to what they can afford to lose. The same odds mean different things for a giant and a startup.", "commonMistake": "Copying a big company's long-shot bet without its cushion.", "mentalModel": "Bet what you can afford to lose."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why Novo tested its obesity drug's ingredient in Alzheimer's if the odds were low.", "prompt": "What's the best explanation?", "options": ["Novo was sure the drug would work there", "Regulators required Novo to run the trials", "Low odds can be worth it for a big prize"], "correctIndex": 2, "consequences": ["One of its own executives called the trials a lottery ticket.", "Novo chose to run them; no rule required it.", "Novo cited a big unmet need despite a low chance of success."], "explanation": "When the payoff is huge, even low odds can justify a trial."}, "proReasoning": "Long shots make sense when the prize is big enough. Many drug trials are planned that way.", "commonMistake": "Assuming companies only run trials they expect to win.", "mentalModel": "Big prize, small odds, still a bet."}}}$ml$::jsonb, ARRAY['handwritten-v1']::text[]),
($ml$da0cbbfd-0e72-5605-b868-e9986862e39e$ml$::uuid, $ml$biotech$ml$, 4, 2, $ml${"id": "biotech-d4-c2", "title": "Pricing a milestone", "lessonTitle": "The odds every drug faces", "slot": 2, "type": "connect", "brief": {"headline": "52% of drugs pass from Phase 1 to Phase 2, and 28.9% from Phase 2 to Phase 3. That is why so much of a deal like Pfizer's is paid only in milestones.", "kicker": "Connect day 2 and day 4: the odds explain why milestones exist.", "fullText": "On day 2, Pfizer paid 3SBio $1.25 billion up front and promised up to $4.8 billion more in milestones tied to trial results, approval and sales. On day 4, you saw why buyers hold most of the money back: from 2011 to 2020, 52% of drugs passed Phase 1, and only 28.9% passed Phase 2.\n\nEach milestone is a bet on one step. A milestone for reaching Phase 2 is far more likely to be paid than one for reaching Phase 3.", "sources": [{"url": "https://www.pfizer.com/news/press-release/press-release-detail/pfizer-enters-exclusive-licensing-agreement-3sbio", "label": "Pfizer, 3SBio licensing deal"}, {"url": "https://go.bio.org/rs/490-EHZ-999/images/ClinicalDevelopmentSuccessRates2011_2020.pdf", "label": "BIO, clinical development success rates 2011-2020"}]}, "evidence": {"kind": "faceOff", "prompt": "Which milestone is more likely to be paid?", "left": {"name": "A milestone for reaching Phase 2", "note": "52% of drugs pass Phase 1"}, "right": {"name": "A milestone for reaching Phase 3", "note": "28.9% of drugs pass Phase 2"}, "correctIndex": 0, "explanation": "Phase 1 passes about half the time. Phase 2 is the hardest step, so its milestone is the riskier one."}, "numbers": {"kind": "numberSense", "prompt": "Of 100 drugs entering Phase 1, about how many reach Phase 3, at 52% and then 28.9%?", "min": 0, "max": 60, "value": 15, "unit": "drugs", "explanation": "100 times 0.52 times 0.289 is about 15. A Phase 3 milestone is paid for about 15 of every 100."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're modeling a licensing deal. One milestone pays when a drug now in Phase 2 enters Phase 3.", "prompt": "What chance do you give it?", "options": ["About 29%, the Phase 2 pass rate", "About 52%, the Phase 1 pass rate", "About 90%, since it is already in trials"], "correctIndex": 0, "consequences": ["28.9% of drugs pass Phase 2, so that is the base rate.", "The 52% is for passing Phase 1, a step it already cleared.", "Being in trials is far from a sure thing."], "explanation": "Use the odds for the step the milestone depends on. Here that is Phase 2, at 28.9%."}, "proReasoning": "Deal modelers attach a phase probability to each milestone. Using the right step is what makes the model credible.", "commonMistake": "Applying one probability to every milestone.", "mentalModel": "Each milestone gets its own odds."}, "invest": {"call": {"kind": "theCall", "situation": "A biotech's partner owes it a big milestone if its Phase 2 drug succeeds.", "prompt": "How do you value that milestone today?", "options": ["Ignore it, since Phase 2 usually fails", "Weight it by roughly a 29% chance", "Count it in full, since it is in the contract"], "correctIndex": 1, "consequences": ["Unlikely is not zero, and 29% still has value.", "Phase 2 to Phase 3 succeeds 28.9% of the time.", "A contract promises payment only if the trial works."], "explanation": "A milestone is worth its size times its odds. For a Phase 2 result, about 29%."}, "proReasoning": "Investors put milestone money into the model at its odds, not its face value. It keeps headline deals in proportion.", "commonMistake": "Counting contingent milestones as cash.", "mentalModel": "Face value times the odds."}, "build_startup": {"call": {"kind": "theCall", "situation": "You're negotiating a deal for your Phase 1 drug. The buyer puts most of the value in a Phase 3 milestone.", "prompt": "What's the risk to you?", "options": ["None, since milestones are guaranteed", "The buyer may pay it too early", "Only about 15 in 100 reach Phase 3"], "correctIndex": 2, "consequences": ["Milestones are paid only if the goal is met.", "Early payment is not the risk; never being paid is.", "You would need to pass two hard steps to collect."], "explanation": "A Phase 3 milestone needs Phase 1 and Phase 2 to succeed first. About 15 in 100 get there."}, "proReasoning": "Founders push value toward nearer milestones and the upfront. Distant milestones are mostly the buyer's protection.", "commonMistake": "Accepting a deal whose value sits behind steps most drugs fail.", "mentalModel": "Pull value closer to today."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend sees a deal \"worth $6 billion\" and asks why the seller only got $1.25 billion now.", "prompt": "What's the reason?", "options": ["Most of the rest depends on long odds", "The buyer will pay the rest next year", "Sellers prefer small upfronts"], "correctIndex": 0, "consequences": ["Only 28.9% of drugs pass Phase 2, so milestones are far from sure.", "Milestones wait for results, not dates.", "Sellers would take more up front if offered."], "explanation": "Each milestone pays only if a hard step succeeds. The buyer holds back most of the money until then."}, "proReasoning": "Deal headlines are best cases built on odds. Most of the money is a bet on results.", "commonMistake": "Reading the headline as a payment schedule.", "mentalModel": "Milestones follow the odds."}}}$ml$::jsonb, ARRAY['handwritten-v1']::text[]),
($ml$a4756f23-4582-526d-aaa3-ca7b85a45bee$ml$::uuid, $ml$biotech$ml$, 4, 3, $ml${"id": "biotech-d4-c3", "title": "The cancer discount", "lessonTitle": "The odds every drug faces", "slot": 3, "type": "decide", "brief": {"headline": "Of drugs entering Phase 1 from 2011 to 2020, 7.9% reached approval. For cancer drugs, it was 5.3%. Phase 2 was the hardest step, with only 28.9% passing.", "kicker": "Decide how the odds change what a program is worth.", "fullText": "BIO, Informa and QLS Advisors studied 12,728 phase transitions across 9,704 programs from 2011 to 2020. The overall likelihood of approval from Phase 1 was 7.9%. For cancer drugs it was 5.3%. Successful drugs took an average of 10.5 years from Phase 1 to approval.\n\nYou run a portfolio of early programs. The day 4 rule applies to each one: a drug's value is its potential payoff times its odds of getting there.", "sources": [{"url": "https://go.bio.org/rs/490-EHZ-999/images/ClinicalDevelopmentSuccessRates2011_2020.pdf", "label": "BIO, clinical development success rates 2011-2020"}]}, "evidence": {"kind": "spotFake", "prompt": "One of these is false. Tap it.", "statements": ["Cancer drugs reached approval from Phase 1 5.3% of the time.", "Phase 2 was the hardest step, passed by 28.9%.", "Cancer drugs had better odds than the average drug."], "fakeIndex": 2, "explanation": "Cancer drugs did worse: 5.3% against 7.9% overall."}, "numbers": {"kind": "numberSense", "prompt": "Suppose a Phase 1 cancer drug would sell $1 billion a year if approved. At 5.3% odds, what is that worth, in millions?", "min": 0, "max": 200, "value": 53, "unit": "M", "explanation": "$1 billion times 5.3% is $53 million a year. The odds shrink the payoff a lot."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You join a biotech portfolio team. Two Phase 1 drugs have the same sales forecast; one treats cancer.", "prompt": "Which carries more risk?", "options": ["Neither, since Phase 1 odds are equal", "The cancer drug, at 5.3% odds", "The other drug, since cancer gets priority"], "correctIndex": 1, "consequences": ["Odds differ by disease area, and cancer is lower.", "Cancer drugs reached approval less often than average.", "Priority does not change the base rate of success."], "explanation": "Same forecast, lower odds. The cancer drug is worth less until it beats its steps."}, "proReasoning": "Portfolio teams adjust odds by disease area. Quoting 5.3% for cancer against 7.9% overall shows you know the base rates.", "commonMistake": "Using one success rate for every disease.", "mentalModel": "Odds depend on the disease."}, "invest": {"call": {"kind": "theCall", "situation": "A cancer biotech's Phase 1 drug could sell $2 billion a year. The CEO says it is worth billions.", "prompt": "What do you do first?", "options": ["Accept billions, since the market is big", "Use the 52% Phase 1 pass rate", "Weight it by about 5% odds"], "correctIndex": 2, "consequences": ["Market size is not value until the odds are applied.", "52% is just passing Phase 1, not reaching approval.", "At 5.3%, $2 billion a year is worth about $106 million a year."], "explanation": "Risk-adjust before you value. Cancer drugs reached approval from Phase 1 only 5.3% of the time."}, "proReasoning": "Investors multiply peak sales by the odds from the current stage. For cancer, that often cuts the value by about 95%.", "commonMistake": "Valuing a Phase 1 drug on its peak sales.", "mentalModel": "Peak sales times the odds."}, "build_startup": {"call": {"kind": "theCall", "situation": "You're choosing your startup's first program. A cancer drug and a non-cancer drug look equally promising.", "prompt": "What should the odds tell you?", "options": ["The cancer drug needs a bigger payoff", "Cancer drugs are easier to get approved", "Odds don't matter at the start"], "correctIndex": 0, "consequences": ["At 5.3% against 7.9%, it must earn more to be worth the same.", "Cancer drugs reached approval less often, not more.", "Odds shape what investors will pay from day one."], "explanation": "Lower odds need a bigger payoff to be worth the same. Founders weigh both."}, "proReasoning": "Founders compare programs on payoff times odds. A slightly smaller market with better odds can win.", "commonMistake": "Picking the biggest market without checking its odds.", "mentalModel": "Lower odds need a bigger prize."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why so many cancers still lack good drugs, given all the money spent.", "prompt": "Which fact helps explain it?", "options": ["The FDA rejects cancer drugs on purpose", "Just 5.3% of cancer drugs reach approval", "Few companies bother working on cancer"], "correctIndex": 1, "consequences": ["The FDA approves those that prove they work.", "Most cancer drugs that reach trials still fail.", "Many try; the low odds show how hard it is."], "explanation": "Cancer drugs fail more often than average. Money buys attempts, not guaranteed results."}, "proReasoning": "Low success rates explain slow progress better than lack of effort. Each approval beats long odds.", "commonMistake": "Assuming slow progress means nobody is trying.", "mentalModel": "Effort is not the same as odds."}}}$ml$::jsonb, ARRAY['handwritten-v1']::text[]),
($ml$c4c4afaf-c678-5313-b531-534e8c5776a4$ml$::uuid, $ml$biotech$ml$, 5, 1, $ml${"id": "biotech-d5-c1", "title": "Promising, but not proven enough", "lessonTitle": "Why every drug must prove it works", "slot": 1, "type": "apply", "brief": {"headline": "In July 2025, the FDA turned down Replimune's melanoma therapy RP1. It said the main trial was not adequate and well controlled enough to give substantial evidence that the drug works.", "kicker": "Apply the burden of proof to a melanoma therapy.", "fullText": "RP1 is an engineered virus given with the immunotherapy nivolumab, for advanced melanoma that got worse on earlier treatment. Its main evidence came from IGNYTE, a single-arm trial. On July 22, 2025, the FDA said the trial could not be adequately interpreted because the patients were too varied, and it asked how much each part of the combination contributed. It raised no safety issues. Replimune said it was surprised.\n\nA second rejection came on April 10, 2026. On August 6, 2026, the FDA granted accelerated approval, on condition that a Phase 3 trial, IGNYTE-3, confirms the benefit.\n\nThe day 5 lesson in action: safety was not the question. Proof that the drug works was, and providing it was Replimune's job.", "sources": [{"url": "https://ir.replimune.com/news-releases/news-release-details/replimune-receives-complete-response-letter-fda-rp1-biologics", "label": "Replimune, complete response letter for RP1, Jul 2025"}, {"url": "https://www.sec.gov/Archives/edgar/data/0001737953/000110465926088857/tm2621708d1_ex99-1.htm", "label": "Replimune, advisory committee outcome for RP1, Jul 2026"}, {"url": "https://www.dermatologytimes.com/view/fda-approves-rp1-plus-nivolumab-for-advanced-melanoma", "label": "Dermatology Times, FDA approves RP1 plus nivolumab for advanced melanoma, Aug 2026"}, {"url": "https://www.everycrsreport.com/reports/RL30989.html", "label": "CRS, The US drug approval process"}]}, "evidence": {"kind": "buildChain", "prompt": "Put RP1's road to approval in order.", "steps": ["A single-arm trial reports responses", "The FDA says the trial is not well controlled", "A second rejection follows in April 2026", "Accelerated approval comes in August 2026", "A Phase 3 trial must confirm the benefit"], "explanation": "Two rejections over the evidence, then a conditional approval that still needs Phase 3 proof."}, "numbers": {"kind": "numberSense", "prompt": "About how many months passed from the first rejection, in July 2025, to approval in August 2026?", "min": 0, "max": 36, "value": 13, "unit": "months", "explanation": "About 13 months, spent arguing over the evidence, not over safety."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You join Replimune's regulatory team in 2025, right after the first rejection.", "prompt": "What's the core job now?", "options": ["Show stronger proof that the drug works", "Argue that the drug is safe enough", "Launch in the US while you appeal it"], "correctIndex": 0, "consequences": ["The letter questioned the evidence of effect, not safety.", "The FDA raised no safety issues, so that was not the gap.", "A rejected drug cannot be sold in the US."], "explanation": "The FDA asked for better evidence of effect. That is what the team had to deliver."}, "proReasoning": "Regulatory teams read a rejection letter for exactly what is missing. Here it was proof of effect, so the answer had to be evidence.", "commonMistake": "Answering a question the FDA did not ask.", "mentalModel": "Answer the question the FDA asked."}, "invest": {"call": {"kind": "theCall", "situation": "A biotech's only drug rests on a single-arm trial, and an FDA decision is near.", "prompt": "What risk should you price in?", "options": ["Only the risk of safety problems", "The FDA may judge the evidence too weak", "None, if the response rate looks good"], "correctIndex": 1, "consequences": ["RP1's letters raised no safety issues at all.", "RP1 was rejected twice on its evidence before approval.", "Good numbers can still fall short of the standard of proof."], "explanation": "The FDA judges how well a trial was controlled, not just its results."}, "proReasoning": "Investors read the trial design before the headline numbers. A single-arm trial carries extra review risk.", "commonMistake": "Treating strong-looking results as proof.", "mentalModel": "Read the design, not just the result."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup is planning its first trial for a cancer therapy. A single-arm design is faster and cheaper.", "prompt": "What does RP1 suggest?", "options": ["Single-arm data is always enough for cancer", "Design the trial after seeing results", "Plan evidence the FDA will see as controlled"], "correctIndex": 2, "consequences": ["RP1's single-arm data was rejected twice first.", "Changing the plan after results weakens the proof.", "Agreeing on the evidence early avoids years of dispute."], "explanation": "The cheaper trial can cost more if the FDA rejects it. Plan for the evidence standard from the start."}, "proReasoning": "Founders design trials backward from the proof the FDA will accept. Saving months on design can cost a year in review.", "commonMistake": "Choosing the cheapest trial without checking it can prove the case.", "mentalModel": "Design for the proof you need."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why the FDA would turn down a cancer drug with no safety problems.", "prompt": "What's the answer?", "options": ["Since 1962, drugs must prove they work", "The FDA only approves cheap drugs", "Cancer drugs need no proof of effect"], "correctIndex": 0, "consequences": ["The 1962 law added proof of effect to the safety rule.", "The FDA's letter was about evidence, not price.", "Every drug must show it works in well-controlled studies."], "explanation": "Safety is not enough. The drugmaker must show, in well-controlled studies, that the drug works."}, "proReasoning": "Approval has two tests: safe and effective. Many rejections are about the second.", "commonMistake": "Thinking the FDA only checks safety.", "mentalModel": "Safe and effective, both proven."}}}$ml$::jsonb, ARRAY['handwritten-v1']::text[]),
($ml$05e6e97b-2b91-56e1-b2c7-d410961b6f2c$ml$::uuid, $ml$biotech$ml$, 5, 2, $ml${"id": "biotech-d5-c2", "title": "Where the proof rule bites", "lessonTitle": "Why every drug must prove it works", "slot": 2, "type": "connect", "brief": {"headline": "Since 1962, a drug must prove it works, not just that it is safe. Phase 2 is the first test of that in several hundred people, and only 28.9% of drugs pass it.", "kicker": "Connect day 4 and day 5: Phase 2 is where proof of effect begins.", "fullText": "On day 5 you saw the 1962 Kefauver-Harris Amendments add a new requirement: proof that a drug works. Trials grow phase by phase. Phase 1 tests safety in fewer than 100 people. Phase 2 tests whether the drug works, in several hundred.\n\nOn day 4 you saw the odds: 52% of drugs pass Phase 1, and only 28.9% pass Phase 2, the hardest step. Phase 2 is where most drugs first face the question the 1962 law made central.", "sources": [{"url": "https://www.everycrsreport.com/reports/RL30989.html", "label": "CRS, The US drug approval process"}, {"url": "https://go.bio.org/rs/490-EHZ-999/images/ClinicalDevelopmentSuccessRates2011_2020.pdf", "label": "BIO, clinical development success rates 2011-2020"}]}, "evidence": {"kind": "multipleChoice", "prompt": "Phase 1 tests safety in fewer than 100 people. What does Phase 2 add?", "options": ["A test of whether it works, in hundreds", "A check of how cheaply it can be made", "The FDA's final approval review"], "correctIndex": 0, "explanation": "Phase 2 tests whether the drug works in several hundred people. Only 28.9% pass."}, "numbers": {"kind": "numberSense", "prompt": "Phase 1 trials usually test safety in fewer than how many people?", "min": 0, "max": 500, "value": 100, "unit": "people", "explanation": "Fewer than 100. Phase 2 grows to several hundred to test whether it works."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're interviewing for a clinical operations role. They ask what makes Phase 2 different.", "prompt": "Which answer is best?", "options": ["It's the FDA's approval review", "It tests whether the drug works", "It's mainly a bigger safety test"], "correctIndex": 1, "consequences": ["Approval review comes after the trials are done.", "Phase 2 is the first real test of effect, in several hundred people.", "Phase 1 handles first safety; Phase 2 adds proof of effect."], "explanation": "Phase 1 asks if it is safe. Phase 2 asks if it works, and most drugs fail there."}, "proReasoning": "Know what each phase is for and how often it fails. Phase 2 is where proof of effect starts, and where 71% of drugs stop.", "commonMistake": "Describing phases only by their size.", "mentalModel": "Each phase asks one question."}, "invest": {"call": {"kind": "theCall", "situation": "A biotech's drug just passed Phase 1 safety testing. The CEO calls it \"de-risked.\"", "prompt": "What do you know?", "options": ["It's now likely to win FDA approval", "It only needs some FDA paperwork now", "Proving it works, the hard part, is ahead"], "correctIndex": 2, "consequences": ["Most drugs that pass Phase 1 still fail later.", "Phase 2 and Phase 3 trials still lie ahead.", "Only 28.9% pass Phase 2, where effect is first tested."], "explanation": "Passing Phase 1 shows early safety. The test of whether it works comes next, and it is the hardest."}, "proReasoning": "Investors know Phase 1 success says little about effect. Real risk falls only after Phase 2.", "commonMistake": "Believing a drug is de-risked after Phase 1.", "mentalModel": "Safety first, proof next."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup's drug finished Phase 1 safely. You're planning what to raise for Phase 2.", "prompt": "What should Phase 2 be built to do?", "options": ["Show clearly whether the drug works", "Repeat the safety results in more people", "Win approval quickly with few patients"], "correctIndex": 0, "consequences": ["A clear answer on effect is what moves a drug and a company.", "Safety matters, but effect is the new question.", "Approval needs well-controlled proof, usually after Phase 3."], "explanation": "Phase 2 must answer whether the drug works. A clear answer, even a no, is worth paying for."}, "proReasoning": "Founders design Phase 2 to give a clear yes or no on effect. A muddy result costs another round of money.", "commonMistake": "Running a Phase 2 too small to answer the question.", "mentalModel": "Pay for a clear answer."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why so many drugs that are safe still fail in trials.", "prompt": "What's the reason?", "options": ["Companies get bored and give up", "Safe isn't enough; they must work too", "The safety tests are usually wrong"], "correctIndex": 1, "consequences": ["They stop because the drug did not work.", "Since 1962, drugs must show they work, and most cannot.", "Many drugs pass safety; effect is the harder test."], "explanation": "Since 1962, drugs must prove they work. Most fail that test in Phase 2."}, "proReasoning": "Most drug failures are about effect, not harm. The proof rule is the reason.", "commonMistake": "Assuming failed drugs were dangerous.", "mentalModel": "Failing often means not working."}}}$ml$::jsonb, ARRAY['handwritten-v1']::text[]),
($ml$30040201-9219-556e-97c7-fe86538c905d$ml$::uuid, $ml$biotech$ml$, 5, 3, $ml${"id": "biotech-d5-c3", "title": "The reviewer and the rule", "lessonTitle": "Why every drug must prove it works", "slot": 3, "type": "decide", "brief": {"headline": "In the early 1960s, thalidomide harmed thousands of babies in Western Europe but was never sold in the US. The 1962 law that followed made drugmakers prove their drugs work.", "kicker": "Decide what counts as proof.", "fullText": "Thalidomide was prescribed to pregnant women for morning sickness. Its US application was still pending when the harm became clear, because an FDA reviewer had serious doubts about its safety, so it was never marketed in the US.\n\nThe scandal led to congressional hearings and the 1962 Kefauver-Harris Amendments. They kept the safety requirements and added proof that a drug works, from adequate and well-controlled studies. The FDA approved 46 novel drugs in 2025 under those rules.\n\nYou run a biotech planning how to prove its drug works. The burden of proof sits with you.", "sources": [{"url": "https://www.everycrsreport.com/reports/RL30989.html", "label": "CRS, The US drug approval process"}, {"url": "https://www.fda.gov/drugs/novel-drug-approvals-fda/novel-drug-approvals-2025", "label": "FDA, novel drug approvals 2025"}]}, "evidence": {"kind": "faceOff", "prompt": "Which evidence better meets the standard the 1962 law set?", "left": {"name": "A well-controlled trial against placebo", "note": "Patients assigned at random, results compared"}, "right": {"name": "Strong stories from treated patients", "note": "Doctors report that many got better"}, "correctIndex": 0, "explanation": "The law asks for adequate, well-controlled studies. Stories cannot show what would have happened without the drug."}, "numbers": {"kind": "numberSense", "prompt": "How many novel drugs did the FDA approve in 2025?", "min": 0, "max": 120, "value": 46, "unit": "drugs", "explanation": "46, each one backed by proof that it works."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're new in regulatory affairs. The team asks what evidence the drug will need.", "prompt": "What do you say first?", "options": ["Proof that it is safe, nothing more", "A panel of doctors' opinions", "Well-controlled studies showing it works"], "correctIndex": 2, "consequences": ["Safety alone has not been enough since 1962.", "Opinions are not adequate, well-controlled studies.", "That has been the standard since 1962."], "explanation": "Approval requires adequate, well-controlled studies showing the drug works, plus safety."}, "proReasoning": "Regulatory teams plan the evidence from the start. Knowing the standard is the core of the job.", "commonMistake": "Planning only for safety data.", "mentalModel": "Plan the proof from day one."}, "invest": {"call": {"kind": "theCall", "situation": "A biotech shares glowing patient stories but has no controlled trial yet.", "prompt": "How close is it to approval?", "options": ["Not close; it needs controlled studies", "Close, since patients are improving", "Ready, if doctors support it"], "correctIndex": 0, "consequences": ["Stories do not meet the proof standard.", "Improvement without a control group proves little.", "Support from doctors does not replace trials."], "explanation": "Without well-controlled studies, there is no proof the drug caused the improvement."}, "proReasoning": "Investors discount anecdotes until controlled data arrives. The FDA does the same.", "commonMistake": "Mistaking patient stories for evidence.", "mentalModel": "No control, no proof."}, "build_startup": {"call": {"kind": "theCall", "situation": "You run a biotech. A controlled trial costs more and takes longer than an open one.", "prompt": "Why pay for it?", "options": ["It makes the drug itself work better", "It's the proof the FDA needs, and a moat", "It's optional, but it looks good to investors"], "correctIndex": 1, "consequences": ["The trial measures the drug; it does not change it.", "The cost of proof keeps rivals out and makes approval possible.", "It is not optional; approval depends on it."], "explanation": "Proof is required, and its cost is also what keeps many newcomers out."}, "proReasoning": "Founders treat the cost of proof as part of the product. It is also what makes an approved drug valuable.", "commonMistake": "Treating the controlled trial as a cost to cut.", "mentalModel": "Proof is the moat."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks how the US avoided the thalidomide disaster.", "prompt": "What's the answer?", "options": ["It was banned worldwide first", "No US doctor would prescribe it", "An FDA reviewer doubted its safety"], "correctIndex": 2, "consequences": ["It was sold in Western Europe, where babies were harmed.", "It never reached US doctors because it was never approved.", "Her doubts kept the application pending until the harm was clear."], "explanation": "One reviewer's doubts held up approval. The harm abroad then led to the 1962 law."}, "proReasoning": "Today's rules came from a near miss. Knowing that history explains why the burden of proof sits with drugmakers.", "commonMistake": "Thinking the rules came from nowhere.", "mentalModel": "The burden of proof was earned by a disaster."}}}$ml$::jsonb, ARRAY['handwritten-v1']::text[]),
($ml$5e99d716-ada2-58c8-ab35-0e189bc07459$ml$::uuid, $ml$biotech$ml$, 6, 1, $ml${"id": "biotech-d6-c1", "title": "56 labs try to repeat the science", "lessonTitle": "When the science does not repeat", "slot": 1, "type": "apply", "brief": {"headline": "In 2025, a Brazilian network of labs reported trying to repeat dozens of published biomedical experiments. Depending on how success was measured, only 15% to 45% held up.", "kicker": "Apply the replication test at national scale.", "fullText": "The Brazilian Reproducibility Initiative picked experiments from Brazilian research using three common methods: a cell metabolism test, a gene amplification method called RT-PCR, and a maze test of anxiety. Several labs repeated each one, and 56 labs finished. In the end, 47 experiments and 97 replications counted as valid. The project cost about US$208,000.\n\nThe results ranged from 15% to 45%, depending on the measure. By one, only 19% of replications were statistically significant. The organizers did not point to fraud. They pointed to methods complex enough to vary between labs, deviations from protocols and incomplete documentation.\n\nThirteen years after Amgen's report, the day 6 lesson held: a finding is not solid until someone repeats it.", "sources": [{"url": "https://elifesciences.org/interviews/388d5959/brazilian-reproducibility-initiative", "label": "eLife, How replicable is biomedical science in Brazil?, 2025"}, {"url": "https://www.the-scientist.com/brazilian-scientists-evaluate-reproducibility-in-biomedical-research-73055", "label": "The Scientist, Brazilian scientists evaluate reproducibility in biomedical research, 2025"}, {"url": "https://www.nbcnews.com/health/health-news/rethinking-how-we-confront-cancer-bad-science-risk-reduction-flna582782", "label": "NBC News, Amgen could replicate only 11% of landmark cancer studies, Mar 2012"}]}, "evidence": {"kind": "spotFake", "prompt": "One of these is false. Tap it.", "statements": ["The project counted 97 valid replications.", "Success ranged from 15% to 45%, by measure.", "The organizers blamed widespread fraud."], "fakeIndex": 2, "explanation": "They pointed to complex methods, protocol deviations and gaps in documentation, not fraud."}, "numbers": {"kind": "numberSense", "prompt": "By one measure, what percent of the replications were statistically significant?", "min": 0, "max": 100, "value": 19, "unit": "%", "explanation": "19%. Across all five measures, success ranged from 15% to 45%."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You join a target validation team. A key paper behind your program comes from a single lab.", "prompt": "What's your first step?", "options": ["Drop it, since most papers fail", "Repeat the key result before building on it", "Trust it, since it passed peer review"], "correctIndex": 1, "consequences": ["Some results do hold up, so test before you discard.", "Only 15% to 45% held up in Brazil's check, so verify first.", "Peer review did not stop many results failing to repeat."], "explanation": "A single-lab result is a lead, not a fact. Repeat it before money follows it."}, "proReasoning": "Validation scientists repeat the core result in-house before a program commits. It is cheap insurance against a wrong target.", "commonMistake": "Treating publication as confirmation.", "mentalModel": "Repeat before you build."}, "invest": {"call": {"kind": "theCall", "situation": "A startup's whole pitch rests on one academic paper's finding.", "prompt": "What do you ask first?", "options": ["How famous is the journal?", "How often has it been cited?", "Has anyone repeated the finding?"], "correctIndex": 2, "consequences": ["Famous journals publish results that fail to repeat too.", "Citations measure attention, not truth.", "Independent repeats are the best test of a finding."], "explanation": "Repeated results are the solid ones. Prestige and citations do not prove a finding holds."}, "proReasoning": "Investors look back at the science before backing a company. Independent replication is the question that matters.", "commonMistake": "Using journal prestige as a stand-in for reliability.", "mentalModel": "Ask who else repeated it."}, "build_startup": {"call": {"kind": "theCall", "situation": "You're thinking of a service that repeats key experiments for drug hunters.", "prompt": "What does the Brazil project suggest your service needs?", "options": ["Clear protocols and full documentation", "Fraud detection, above everything else", "As few repeats per result as possible"], "correctIndex": 0, "consequences": ["Deviations and gaps in documentation drove many failures.", "Organizers pointed to methods, not fraud.", "They recommended more repeats per experiment, not fewer."], "explanation": "The project found methods and documentation were the weak points. That is where a service adds value."}, "proReasoning": "Founders build where the failure actually happens. Here it was in methods and documentation.", "commonMistake": "Building for a dramatic cause instead of the common one.", "mentalModel": "Fix the real failure point."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend sees a news story about a cool lab discovery and asks if a drug is coming soon.", "prompt": "What should you tell them?", "options": ["No, lab results never matter", "First, others need to repeat it", "Yes, published results are proven"], "correctIndex": 1, "consequences": ["Repeated findings are where drugs start.", "Many results don't hold up when other labs try them.", "Only 15% to 45% held up in the Brazil project."], "explanation": "A single study is a first step. Replication comes before anyone bets years on it."}, "proReasoning": "One study is news, not knowledge. Repeated results are what drug discovery builds on.", "commonMistake": "Treating one published result as settled.", "mentalModel": "One study is a start."}}}$ml$::jsonb, ARRAY['handwritten-v1']::text[]),
($ml$814bc71f-38fc-50ab-8294-e216e360f38f$ml$::uuid, $ml$biotech$ml$, 6, 2, $ml${"id": "biotech-d6-c2", "title": "A wrong target fails late", "lessonTitle": "When the science does not repeat", "slot": 2, "type": "connect", "brief": {"headline": "Drug discovery starts with a target, often taken from published biology. Amgen could confirm only 6 of 53 landmark cancer studies. A wrong target can pass discovery and fail years later in people.", "kicker": "Connect day 1 and day 6: a shaky target fails years later.", "fullText": "On day 1 you saw discovery start with a target, a molecule in the body linked to a disease. Everything after, from hits to the IND, rests on that choice.\n\nOn day 6 you saw Amgen confirm the findings of only 6 of 53 landmark preclinical cancer studies, about 11%. If a drug's target came from a finding that does not hold, the drug can pass discovery and fail in human trials years later, when the costs are far higher.", "sources": [{"url": "https://www.cambridgemedchemconsulting.com/resources/stages.html", "label": "Cambridge MedChem, drug discovery stages"}, {"url": "https://www.nbcnews.com/health/health-news/rethinking-how-we-confront-cancer-bad-science-risk-reduction-flna582782", "label": "NBC News, Amgen could replicate only 11% of landmark cancer studies, Mar 2012"}]}, "evidence": {"kind": "buildChain", "prompt": "Follow how a shaky target turns into a costly failure.", "steps": ["A paper links a molecule to a disease", "A team picks it as its target", "Screening and chemistry yield a candidate", "The candidate enters human trials", "Trials fail because the target was wrong"], "explanation": "The mistake happens first and shows up last. By then years and money are spent."}, "numbers": {"kind": "numberSense", "prompt": "Amgen confirmed 6 of 53 landmark cancer studies. About what percent is that?", "min": 0, "max": 50, "value": 11, "unit": "%", "explanation": "6 divided by 53 is about 11%. Nearly nine in ten did not hold up."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're interviewing for a discovery biologist role. They ask how you would choose a target.", "prompt": "Which answer is best?", "options": ["Pick the most cited target in the field", "Let screening results pick the target", "Confirm the published link before chemistry"], "correctIndex": 2, "consequences": ["Popular findings can still fail to repeat.", "Screening needs a target first; it cannot choose one.", "Every later stage rests on the target being right."], "explanation": "The target comes first, so checking it first protects every stage after."}, "proReasoning": "Strong candidates explain how they would validate a target. Amgen's 6 of 53 is the classic reason why.", "commonMistake": "Treating target choice as a quick step before the real work.", "mentalModel": "Check the foundation first."}, "invest": {"call": {"kind": "theCall", "situation": "A biotech's drug failed in Phase 2. Its target came from one study nobody had repeated.", "prompt": "What's the lesson for your next bet?", "options": ["Check the target evidence before trials", "Phase 2 failures are mostly bad luck", "Back only drugs from big companies"], "correctIndex": 0, "consequences": ["A wrong target fails late, after the money is spent.", "Some failures trace back to a shaky starting point.", "Big companies build on published biology too."], "explanation": "Late failures often start with early choices. Ask how the target was validated."}, "proReasoning": "Investors trace failures back to their root. A target with independent replication cuts one big risk.", "commonMistake": "Blaming every trial failure on chance.", "mentalModel": "Trace failures to the target."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup licenses an academic target. Investors ask how you'll avoid Amgen's 6-of-53 problem.", "prompt": "What's your answer?", "options": ["We move fast and fix problems later", "We repeat the core finding before scaling", "We trust the original lab's reputation"], "correctIndex": 1, "consequences": ["A wrong target cannot be fixed later, only abandoned.", "A small upfront cost protects years of work.", "Amgen's failed studies came from competent labs."], "explanation": "Repeating the key result early is cheap. Finding out in trials is not."}, "proReasoning": "Founders budget a replication step before chemistry. It answers investors' first question.", "commonMistake": "Skipping replication to look fast.", "mentalModel": "Pay a little early, save a lot later."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks how a drug can fail in trials after years of careful lab work.", "prompt": "Which reason fits what you learned?", "options": ["Lab work is never done carefully", "Trials are designed to make drugs fail", "Its target may have been wrong"], "correctIndex": 2, "consequences": ["The lab work can be careful and still built on a bad target.", "Trials test the drug fairly; many drugs just fail.", "A shaky finding at the start can sink the drug at the end."], "explanation": "If the target was wrong, good chemistry cannot save the drug."}, "proReasoning": "Some failures are decided at the very first step. A drug is only as good as its target.", "commonMistake": "Blaming the last step for a mistake made at the first.", "mentalModel": "A drug is only as good as its target."}}}$ml$::jsonb, ARRAY['handwritten-v1']::text[]),
($ml$98665a6e-5ebe-5fa6-bcac-1fb0fe0feff7$ml$::uuid, $ml$biotech$ml$, 6, 3, $ml${"id": "biotech-d6-c3", "title": "Build on it, or repeat it first?", "lessonTitle": "When the science does not repeat", "slot": 3, "type": "decide", "brief": {"headline": "Amgen confirmed only 6 of 53 landmark cancer studies, and a Bayer team had reported similar problems. Begley and Ellis assumed the authors were competent and honest.", "kicker": "Decide which findings are ready to build on.", "fullText": "In 2012, Glenn Begley, then head of cancer research at Amgen, and Lee Ellis of MD Anderson reported that Amgen could confirm only 6 of 53 landmark preclinical cancer studies. The studies were done in cells and rodents. A Bayer team had reported similar problems a year earlier. Begley and Ellis assumed fraud played little or no role.\n\nYou run discovery at a biotech, choosing which published findings to turn into programs. The day 6 rule: a finding is not solid until someone repeats it.", "sources": [{"url": "https://www.nbcnews.com/health/health-news/rethinking-how-we-confront-cancer-bad-science-risk-reduction-flna582782", "label": "NBC News, Amgen could replicate only 11% of landmark cancer studies, Mar 2012"}, {"url": "https://english.ahram.org.eg/News/37975.aspx", "label": "Reuters via Ahram Online, In cancer science, many discoveries don't hold up, Mar 2012"}]}, "evidence": {"kind": "sortSignal", "prompt": "Sort each finding: repeat it first, or ready to build on?", "buckets": ["Repeat it first", "Ready to build on"], "items": [{"text": "A single lab's cell study, never repeated", "bucket": 0}, {"text": "A mouse result from one famous paper", "bucket": 0}, {"text": "A result that only works in the original lab", "bucket": 0}, {"text": "A finding confirmed by two independent labs", "bucket": 1}, {"text": "A result your own team has reproduced", "bucket": 1}], "explanation": "Fame and novelty do not make a finding solid. Independent repeats do."}, "numbers": {"kind": "numberSense", "prompt": "Of the 53 landmark studies, how many could Amgen not confirm?", "min": 0, "max": 60, "value": 47, "unit": "studies", "explanation": "53 minus 6 is 47, the large majority."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You lead a small discovery team with budget for one new program. A hot paper just named a new target.", "prompt": "What do you do?", "options": ["Spend a little to repeat it, then decide", "Commit the whole budget before rivals do", "Skip it, since hot papers never hold up"], "correctIndex": 0, "consequences": ["A small test protects the whole budget.", "Amgen's 6 of 53 shows how often that bet goes wrong.", "Some do hold up, so test before you decide."], "explanation": "Repeat the key experiment first. It costs little next to a failed program."}, "proReasoning": "Good discovery leads stage their spending: a cheap repeat, then a real commitment. Speed matters less than being right.", "commonMistake": "Racing rivals onto a target nobody has confirmed.", "mentalModel": "Test cheap, then commit."}, "invest": {"call": {"kind": "theCall", "situation": "You're doing due diligence on a seed-stage biotech built on a recent paper.", "prompt": "Which fact most raises your confidence?", "options": ["The paper made headlines", "The company reproduced the result itself", "The paper's authors are well known"], "correctIndex": 1, "consequences": ["Headlines measure interest, not reliability.", "A repeat in a new lab is the best evidence it holds.", "Amgen's failed studies came from respected scientists."], "explanation": "Reproduction by a second team is the strongest sign a finding is real."}, "proReasoning": "Investors ask for the replication data, not the press coverage. It is the first filter on early science.", "commonMistake": "Backing a company on the authors' reputation.", "mentalModel": "Reproduced beats renowned."}, "build_startup": {"call": {"kind": "theCall", "situation": "You founded a startup on your own PhD finding. An investor asks for independent confirmation.", "prompt": "What's the best response?", "options": ["Point to your paper's peer review", "Say confirmation would slow you down", "Pay an outside lab to repeat it"], "correctIndex": 2, "consequences": ["Peer review did not stop most of the 53 from failing.", "Skipping it looks like you fear the answer.", "An outside repeat answers the doubt directly."], "explanation": "An independent repeat turns your finding into evidence an investor can trust."}, "proReasoning": "Founders who fund their own replication show confidence and remove a major risk. Investors notice.", "commonMistake": "Defending the finding instead of testing it.", "mentalModel": "Invite the test."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend says Amgen's result proves cancer research is fraud.", "prompt": "What's the fairest answer?", "options": ["No; fraud was thought to play little role", "Yes, most cancer labs fake their data", "Nobody knows who ran those studies"], "correctIndex": 0, "consequences": ["Begley and Ellis assumed little or no fraud.", "The report blamed hard science, not faked data.", "The studies were published by known researchers."], "explanation": "Begley and Ellis called the original researchers competent and well-meaning. Biology is hard to repeat."}, "proReasoning": "Failed replication usually means fragile results, not fake ones. That is why repeating matters.", "commonMistake": "Jumping from \"did not repeat\" to \"was faked.\"", "mentalModel": "Fragile is not fake."}}}$ml$::jsonb, ARRAY['handwritten-v1']::text[]),
($ml$98b6a8b1-2840-5853-8999-05ad57a8049e$ml$::uuid, $ml$biotech$ml$, 7, 1, $ml${"id": "biotech-d7-c1", "title": "A pig kidney clears the FDA gate", "lessonTitle": "What a drug must show before people", "slot": 1, "type": "apply", "brief": {"headline": "In February 2025, the FDA cleared United Therapeutics' IND to test kidneys from gene-edited pigs in people. The first transplant in the trial, called EXPAND, was announced in November 2025.", "kicker": "Apply the IND to a pig kidney.", "fullText": "The UKidney comes from a pig with 10 gene edits: six human genes added to help the human immune system accept the organ, and four pig genes switched off, three linked to rejection and one to organ overgrowth. On February 3, 2025, the FDA cleared United Therapeutics' IND for a clinical study.\n\nThe trial plan is detailed. It starts with six patients with end-stage kidney disease, aged 55 to 70 and on dialysis for at least six months, at two transplant centers. There is a 12-week wait between the first and second transplants, and an independent committee reviews the data once the first group reaches 12 weeks. If results support it, the study can grow to 50 patients. The first transplant, at NYU Langone Health, was announced on November 3, 2025.\n\nEvery IND, for a pill or a pig kidney, covers the same three areas: safety studies, what the product is and how it is made, and the trial plan with the people who will run it.", "sources": [{"url": "https://www.businesswire.com/news/home/20250203431557/en/United-Therapeutics-Corporation-Announces-FDA-Clearance-of-its-Investigational-New-Drug-Application-for-the-UKidney-Xenotransplantation-Clinical-Trial", "label": "United Therapeutics, FDA clears IND for the UKidney trial, Feb 2025"}, {"url": "https://www.businesswire.com/news/home/20251103435431/en/United-Therapeutics-Corporation-Announces-First-Transplant-in-EXPAND-Clinical-Trial-of-UKidney-in-Patients-With-End-Stage-Renal-Disease", "label": "United Therapeutics, first transplant in the EXPAND trial, Nov 2025"}, {"url": "https://en.wikipedia.org/wiki/Investigational_New_Drug", "label": "Investigational New Drug application, overview"}]}, "evidence": {"kind": "sortSignal", "prompt": "Which part of the UKidney IND does each detail belong to?", "buckets": ["What the product is", "The trial plan"], "items": [{"text": "Six human genes added to the pig", "bucket": 0}, {"text": "Four pig genes switched off", "bucket": 0}, {"text": "Six patients aged 55 to 70 to start", "bucket": 1}, {"text": "A 12-week wait between the first two transplants", "bucket": 1}, {"text": "Two transplant centers in the first group", "bucket": 1}], "explanation": "The gene edits describe the product. Patients, sites and timing make up the trial plan."}, "numbers": {"kind": "numberSense", "prompt": "If results support it, the EXPAND study can grow to how many patients?", "min": 0, "max": 120, "value": 50, "unit": "patients", "explanation": "Up to 50, starting from six. The trial plan sets each step before it begins."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're interviewing for a clinical operations role on a first-in-human study like EXPAND.", "prompt": "Which part of the IND would you own?", "options": ["The gene edits and how the pigs are made", "The animal toxicity studies", "The trial plan: patients, sites and schedule"], "correctIndex": 2, "consequences": ["That's product and manufacturing work, not clinical operations.", "Toxicologists own the animal safety studies.", "Protocols and investigator details are the trial plan's job."], "explanation": "An IND splits into safety, manufacturing and the trial plan. Clinical operations runs the trial plan."}, "proReasoning": "Know which part of the IND each team owns. It tells an interviewer you understand how the work is divided.", "commonMistake": "Describing the IND as one document that only regulatory touches.", "mentalModel": "Three parts, three owners."}, "invest": {"call": {"kind": "theCall", "situation": "United Therapeutics announces that its IND has cleared for a pig kidney trial.", "prompt": "What does the clearance tell you?", "options": ["Trials can start; approval is far off", "The FDA has approved the pig kidney", "The trial results came back positive"], "correctIndex": 0, "consequences": ["Clearance opens a trial that must still show safety and benefit.", "Clearance is permission to test, not approval to sell.", "No patient in the trial had been treated yet."], "explanation": "An IND taking effect lets trials begin. The study itself must still deliver results."}, "proReasoning": "Investors track IND clearance as a milestone, then reset the clock. The real test begins with the first patients.", "commonMistake": "Reading IND clearance as a verdict on the product.", "mentalModel": "Cleared to test, not cleared to sell."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup makes a gene-edited tissue product. You are planning your first IND.", "prompt": "What must you prepare besides the trial plan?", "options": ["Proof that patients will pay for it", "Safety studies and how you make the product", "A list of hospitals that want to join"], "correctIndex": 1, "consequences": ["Price is not one of the three IND areas.", "The IND needs safety data and manufacturing details too.", "Sites are one piece; safety and manufacturing are the others."], "explanation": "An IND covers safety studies, manufacturing and the trial plan. All three must be ready."}, "proReasoning": "Founders plan all three IND areas in parallel. A gap in any one of them can hold up the first patient.", "commonMistake": "Polishing the trial plan while safety or manufacturing lags.", "mentalModel": "All three parts, or no trial."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend heard that the FDA \"approved pig kidney transplants\" in 2025.", "prompt": "What's more accurate?", "options": ["It approved them for all kidney patients", "It banned them after one failed transplant", "It cleared a trial, not a treatment for sale"], "correctIndex": 2, "consequences": ["Only patients in the trial can receive the kidney.", "The FDA cleared the study in February 2025.", "The IND let a study starting with six patients begin."], "explanation": "An IND lets a company test in people. Approval comes only after trials show it works."}, "proReasoning": "Listen for the word trial in health news. Permission to test is not permission to sell.", "commonMistake": "Hearing \"FDA clears\" and thinking \"FDA approves.\"", "mentalModel": "Cleared to test is not approved."}}}$ml$::jsonb, ARRAY['handwritten-v1']::text[]),
($ml$2d2abd22-43ca-510a-859f-17bf8d14cff6$ml$::uuid, $ml$biotech$ml$, 7, 2, $ml${"id": "biotech-d7-c2", "title": "Cleared, but at long odds", "lessonTitle": "What a drug must show before people", "slot": 2, "type": "connect", "brief": {"headline": "An IND takes effect if the FDA does not object within 30 days, and human trials can begin. Yet only 7.9% of drugs entering Phase 1 went on to win approval.", "kicker": "Connect day 4 and day 7: an IND opens the door, not the finish line.", "fullText": "On day 7 you saw what the FDA reviews in an IND: animal pharmacology and toxicology studies, manufacturing information, and clinical protocols. If the FDA does not object within 30 days, trials can start.\n\nOn day 4 you saw the odds after that. From 2011 to 2020, 52% of drugs passed Phase 1, 28.9% passed Phase 2, and 7.9% of those entering Phase 1 reached approval. Clearing the IND is a real milestone. It is also the start of the hardest part.", "sources": [{"url": "https://en.wikipedia.org/wiki/Investigational_New_Drug", "label": "Investigational New Drug application, overview"}, {"url": "https://go.bio.org/rs/490-EHZ-999/images/ClinicalDevelopmentSuccessRates2011_2020.pdf", "label": "BIO, clinical development success rates 2011-2020"}]}, "evidence": {"kind": "multipleChoice", "prompt": "An IND has just taken effect. What comes next, and how often is it passed?", "options": ["Phase 3, passed by about 29%", "Phase 1, passed by about 52%", "Approval, granted to about 52%"], "correctIndex": 1, "explanation": "The IND opens Phase 1, which about 52% of drugs pass. Approval is several steps away."}, "numbers": {"kind": "numberSense", "prompt": "Of 100 drugs entering Phase 1, about how many never reach approval?", "min": 0, "max": 100, "value": 92, "unit": "drugs", "explanation": "About 92 of 100. Only 7.9% of drugs entering Phase 1 were approved."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're a toxicologist whose studies supported an IND that just took effect. The team is celebrating.", "prompt": "What's the right perspective?", "options": ["A milestone, with most of the risk ahead", "The drug is now likely to reach approval", "Our safety work no longer matters"], "correctIndex": 0, "consequences": ["Only 7.9% of drugs entering Phase 1 reach approval.", "Most drugs entering trials still fail.", "Your safety data is what let the first doses begin."], "explanation": "The IND is the gate to trials. Most of the risk lies on the other side of it."}, "proReasoning": "Experienced scientists celebrate milestones and keep the odds in view. It makes them credible in planning.", "commonMistake": "Treating the IND as the finish line.", "mentalModel": "A gate, not a goal."}, "invest": {"call": {"kind": "theCall", "situation": "A biotech's stock jumps after its IND takes effect.", "prompt": "How should you read the move?", "options": ["It means nothing at all for value", "Real progress, but odds stay near 8%", "Approval is now very likely to follow"], "correctIndex": 1, "consequences": ["Starting trials is a real step toward value.", "Phase 1 has begun, and 7.9% of drugs at this stage are approved.", "From Phase 1, most drugs still fail."], "explanation": "An IND is worth tracking, but the odds from Phase 1 are still long."}, "proReasoning": "Investors watch for IND clearance and then risk-adjust from the new stage. The odds improve only as phases are passed.", "commonMistake": "Pricing an IND as if approval were near.", "mentalModel": "Milestone, then risk-adjust."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup's IND just took effect. An investor offers funding only through Phase 1.", "prompt": "What should you plan for?", "options": ["Reaching approval within two years", "Needing no more money after this round", "Raising again before the Phase 2 step"], "correctIndex": 2, "consequences": ["Approved drugs averaged 10.5 years from Phase 1 to approval.", "Phase 2 and Phase 3 still lie ahead and need funding.", "Phase 2, passed by 28.9%, will need its own funding."], "explanation": "Phase 1 funding gets you to the next question. Plan the next raise before you need it."}, "proReasoning": "Founders fund one phase at a time and plan the next raise early. Each phase passed is what earns the next round.", "commonMistake": "Assuming the IND round will carry the company to approval.", "mentalModel": "Fund the phase, plan the next."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend reads that a company \"got FDA clearance\" for its drug and thinks it will be on shelves soon.", "prompt": "What's the truth?", "options": ["It can start trials, at long odds", "It's approved and launching soon", "It was rejected by the FDA"], "correctIndex": 0, "consequences": ["Most drugs that start trials never reach approval.", "Clearance lets trials begin; approval comes years later, if ever.", "Clearance is a yes to testing, not a rejection."], "explanation": "IND clearance means trials can begin. Only about 8 in 100 drugs at that point are approved."}, "proReasoning": "News about a drug often means an early step. Ask which step, and remember the odds.", "commonMistake": "Confusing permission to test with approval.", "mentalModel": "Ask which step it is."}}}$ml$::jsonb, ARRAY['handwritten-v1']::text[]),
($ml$5cbe25ca-7fc7-5bfa-acdb-e8ff832b335a$ml$::uuid, $ml$biotech$ml$, 7, 3, $ml${"id": "biotech-d7-c3", "title": "Ready to file?", "lessonTitle": "What a drug must show before people", "slot": 3, "type": "decide", "brief": {"headline": "An IND covers three areas: animal safety studies, manufacturing details, and clinical protocols with investigator information. The FDA then has 30 days to object or impose a clinical hold.", "kicker": "Decide what your IND still needs.", "fullText": "You run a small biotech getting ready to file its first IND. Animal pharmacology and toxicology studies must show the drug is reasonably safe for first human testing. Manufacturing information must cover the drug's composition, stability and controls, showing you can make consistent batches. Clinical protocols lay out the trial, and investigator details show who will run it.\n\nAfter you file, the FDA has 30 days. If it does not object, the IND takes effect and trials can begin. If it finds a problem, it can place a clinical hold.", "sources": [{"url": "https://en.wikipedia.org/wiki/Investigational_New_Drug", "label": "Investigational New Drug application, overview"}]}, "evidence": {"kind": "buildChain", "prompt": "Put the path to the first human dose in order.", "steps": ["Pick the candidate", "Run animal safety studies", "File the IND with all three parts", "Wait 30 days for FDA objections", "Dose the first patient"], "explanation": "Safety studies feed the IND. Only after the 30-day review passes can the first person be dosed."}, "numbers": {"kind": "numberSense", "prompt": "You file your IND on day 0. On what day, at the earliest, can trials begin if the FDA does not object?", "min": 0, "max": 90, "value": 30, "unit": "days", "explanation": "Day 30. Any objection before then can turn into a clinical hold."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You manage an IND. Toxicology is done, but the manufacturing team lacks stability data.", "prompt": "What do you do?", "options": ["Drop the manufacturing section for now", "Wait for the stability data, then file", "File now and add the data in a few weeks"], "correctIndex": 1, "consequences": ["The IND must cover composition, stability and controls.", "Stability is part of the manufacturing section the FDA reviews.", "A gap in the filing invites a clinical hold."], "explanation": "A complete IND avoids a hold. Stability data belongs in the manufacturing section."}, "proReasoning": "Project leads check all three IND areas before filing. A missing piece can cost more time than waiting for it.", "commonMistake": "Filing early with a known gap.", "mentalModel": "Complete beats early."}, "invest": {"call": {"kind": "theCall", "situation": "A biotech says it will dose its first patient 30 days after filing its IND.", "prompt": "What's the risk to that timeline?", "options": ["None, since the 30 days is guaranteed", "The FDA always takes a full year to act", "A clinical hold if problems are found"], "correctIndex": 2, "consequences": ["The 30 days is a window to object, not a promise.", "If the FDA does not object, 30 days is enough.", "A hold stops trials until the questions are answered."], "explanation": "Thirty days is the best case. A clinical hold can push the first dose back by months."}, "proReasoning": "Investors treat the 30-day date as a best case. Holds are the risk to model.", "commonMistake": "Treating the 30-day window as certain.", "mentalModel": "30 days is the best case."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your cash covers either a full toxicology package or a faster, partial one.", "prompt": "Which is wiser?", "options": ["The full package the FDA expects", "The partial one, so you can file sooner", "Skip toxicology; trials will show safety"], "correctIndex": 0, "consequences": ["Safety studies must show the drug is reasonably safe to try.", "A thin package risks a hold that costs more time.", "No human dosing happens without the safety section."], "explanation": "The IND is paid for up front. Cutting the safety work risks the very delay you hoped to avoid."}, "proReasoning": "Founders budget the full IND package before human data exists. It is one of the first big cash needs.", "commonMistake": "Saving money on the studies that open the door to trials.", "mentalModel": "Pay for the IND up front."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks what the FDA checks before anyone takes a new drug.", "prompt": "What's the best summary?", "options": ["Just the company's finances and staff", "Safety data, manufacturing, trial plan", "Only whether the drug actually works"], "correctIndex": 1, "consequences": ["The IND is about safety and the trial, not money.", "Those are the three areas of every IND.", "Whether it works is tested later, in trials."], "explanation": "The IND covers safety studies, manufacturing and the trial plan. The FDA has 30 days to object."}, "proReasoning": "Every new drug passes this check before a first dose. It is the first FDA gate.", "commonMistake": "Thinking the first FDA review tests whether the drug works.", "mentalModel": "Safe to try, made right, planned well."}}}$ml$::jsonb, ARRAY['handwritten-v1']::text[]),
($ml$574205db-de98-50b9-9470-8bf7cdba9896$ml$::uuid, $ml$biotech$ml$, 8, 1, $ml${"id": "biotech-d8-c1", "title": "When biotech clients cancel", "lessonTitle": "Who runs the safety studies", "slot": 1, "type": "apply", "brief": {"headline": "In the first quarter of 2025, Medpace, a CRO whose clients are mostly small biotechs, booked $500 million of new business, down 18.8%. It blamed elevated cancellations on clients' funding troubles.", "kicker": "Apply the money flow from biotechs to the labs they hire.", "fullText": "Medpace runs clinical studies for drug companies, and small biopharma clients make up about 80% of its revenue. In the first quarter of 2025, its revenue rose 9.3% to $558.6 million, from work already booked. But net new business awards fell 18.8% to $500 million, a book-to-bill ratio of 0.90, and its backlog shrank 2.1%.\n\nManagement called the cancellations broad-based, tied mainly to clients' funding difficulties and some drug failures.\n\nThis is the day 8 flow. When biotechs raise money, much of it goes to outside labs. When their funding tightens, the labs' new bookings fall first, while revenue from older bookings keeps arriving for a while.", "sources": [{"url": "https://www.biospace.com/press-releases/medpace-holdings-inc-reports-first-quarter-2025-results", "label": "Medpace, first quarter 2025 results, Apr 2025"}, {"url": "https://business.mammothtimes.com/mammothtimes/article/stockstory-2025-5-10-medp-q1-earnings-call-outperformance-driven-by-revenue-upside-cautious-outlook-amid-funding-uncertainty", "label": "StockStory, Medpace Q1 2025 earnings call, May 2025"}, {"url": "https://www.businesswire.com/news/home/20260218016453/en/Charles-River-Laboratories-Announces-Fourth-Quarter-and-Full-Year-2025-Results-and-Provides-2026-Guidance", "label": "Charles River Laboratories, fourth quarter and full year 2025 results, Feb 2026"}]}, "evidence": {"kind": "multipleChoice", "prompt": "Medpace's revenue rose 9.3% while new bookings fell 18.8%. What does that suggest?", "options": ["Demand from biotechs is rising fast", "Medpace raised its prices sharply", "Old work still bills; new work is slowing"], "correctIndex": 2, "explanation": "Revenue comes from past bookings. Falling new bookings point to slower revenue later."}, "numbers": {"kind": "numberSense", "prompt": "About what percent of Medpace's revenue comes from small biopharma clients?", "min": 0, "max": 100, "value": 80, "unit": "%", "explanation": "About 80%, which is why their funding troubles hit Medpace so directly."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're interviewing at a CRO in mid-2025. They ask what drives the business.", "prompt": "What's the best answer?", "options": ["Biotech funding; small clients pay most", "Government grants for basic research", "Hospital budgets for patient care"], "correctIndex": 0, "consequences": ["Small biopharma made up about 80% of Medpace's revenue.", "CRO clients are drug companies paying for studies.", "Drug companies, not hospitals, pay for these studies."], "explanation": "A CRO's demand follows its clients' cash. For Medpace, that means small biotechs."}, "proReasoning": "Explain who pays a CRO and where their money comes from. It shows you understand the whole chain.", "commonMistake": "Describing a CRO without naming who funds its clients.", "mentalModel": "Follow the client's cash."}, "invest": {"call": {"kind": "theCall", "situation": "A CRO's revenue is still growing, but new bookings fell and cancellations rose.", "prompt": "What do you watch next?", "options": ["Where the CRO's offices are located", "Whether bookings recover next quarter", "Only this quarter's revenue growth"], "correctIndex": 1, "consequences": ["Location says little about demand.", "Bookings today become revenue later, so they lead.", "Revenue reflects older bookings, so it lags."], "explanation": "Bookings lead revenue. A drop shows up in sales a few quarters later."}, "proReasoning": "Investors read CRO bookings as a gauge of biotech spending. Revenue tells you about the past.", "commonMistake": "Trusting revenue growth when bookings are falling.", "mentalModel": "Bookings lead, revenue lags."}, "build_startup": {"call": {"kind": "theCall", "situation": "You plan to start a small CRO serving early-stage biotechs in 2025.", "prompt": "What risk does Medpace's quarter flag?", "options": ["Big drugmakers will take all your clients", "Nobody pays for outside studies anymore", "Clients cancel when their funding dries up"], "correctIndex": 2, "consequences": ["Medpace's pressure came from small clients' funding.", "Medpace still booked $500 million in one quarter.", "Medpace tied cancellations to clients' funding troubles."], "explanation": "When clients depend on raising money, your bookings depend on it too."}, "proReasoning": "Founders of service businesses study their clients' funding. A cash crunch upstream becomes cancellations downstream.", "commonMistake": "Assuming signed work is safe when clients are short of cash.", "mentalModel": "Your clients' funding is your risk."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks how a slowdown in biotech investing could hurt a company that runs studies.", "prompt": "What's the link?", "options": ["Biotechs pay CROs with the money they raise", "CROs invest their cash in biotech stocks", "Investors run the studies themselves"], "correctIndex": 0, "consequences": ["Less money raised means fewer studies booked.", "CROs earn fees for studies, not stock gains.", "Investors fund biotechs, which hire the CROs."], "explanation": "Investor money flows to biotechs, then on to the labs they hire."}, "proReasoning": "Follow the money one more step than the headline. Funding news shows up in service companies next.", "commonMistake": "Thinking funding only affects the biotechs that raise it.", "mentalModel": "Money flows downstream."}}}$ml$::jsonb, ARRAY['handwritten-v1']::text[]),
($ml$b204c580-8110-5fc5-90be-4943be5ec2b8$ml$::uuid, $ml$biotech$ml$, 8, 2, $ml${"id": "biotech-d8-c2", "title": "Who writes the IND's safety section?", "lessonTitle": "Who runs the safety studies", "slot": 2, "type": "connect", "brief": {"headline": "Every IND needs animal pharmacology and toxicology studies. Many biotechs buy them: Charles River's discovery and safety unit, which runs that kind of work, earned $2.40 billion in 2025.", "kicker": "Connect day 7 and day 8: the IND's safety studies are often bought.", "fullText": "On day 7 you saw the IND's safety section: animal pharmacology and toxicology studies showing a drug is reasonably safe to try in people. On day 8 you saw who often runs them: contract research organizations. Charles River's Discovery and Safety Assessment segment, which runs studies such as the toxicology work behind an IND, earned $2.40 billion in 2025, out of total revenue of $4.02 billion.\n\nPut them together. A biotech raises money, pays a CRO for safety studies, and files an IND built partly on that work.", "sources": [{"url": "https://en.wikipedia.org/wiki/Investigational_New_Drug", "label": "Investigational New Drug application, overview"}, {"url": "https://www.businesswire.com/news/home/20260218016453/en/Charles-River-Laboratories-Announces-Fourth-Quarter-and-Full-Year-2025-Results-and-Provides-2026-Guidance", "label": "Charles River Laboratories, fourth quarter and full year 2025 results, Feb 2026"}]}, "evidence": {"kind": "buildChain", "prompt": "Follow the money from a biotech's raise to its IND.", "steps": ["A biotech raises money from investors", "It hires a CRO for toxicology studies", "The CRO runs the animal safety work", "The results go into the IND", "The FDA's 30-day review begins"], "explanation": "Raised money pays the lab, the lab produces the safety data, and the data goes into the IND."}, "numbers": {"kind": "numberSense", "prompt": "Charles River's 2025 revenue was $4.02 billion. About what percent came from discovery and safety?", "min": 0, "max": 100, "value": 60, "unit": "%", "explanation": "2.40 divided by 4.02 is about 60%. Safety work is most of the business."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're a toxicologist choosing between a CRO and a small biotech.", "prompt": "What's true about the CRO job?", "options": ["CROs don't run any safety studies", "You'd run safety studies for many clients", "You'd work on one company's drug only"], "correctIndex": 1, "consequences": ["Safety studies are a CRO's core work.", "CROs run the studies many biotechs buy for their INDs.", "That describes the biotech job, not the CRO."], "explanation": "CROs run safety studies for many paying clients. Biotechs focus on their own drugs."}, "proReasoning": "Know the trade-off: a CRO gives breadth across many drugs, a biotech gives depth in one. Both feed the same IND.", "commonMistake": "Not knowing where most IND safety work is done.", "mentalModel": "Breadth at a CRO, depth at a biotech."}, "invest": {"call": {"kind": "theCall", "situation": "Biotech funding slows, and fewer drugs head toward an IND.", "prompt": "Which business feels it early?", "options": ["A company selling approved generics", "A hospital chain treating patients", "A CRO running preclinical safety studies"], "correctIndex": 2, "consequences": ["Generic sales depend on prescriptions, not on new INDs.", "Hospitals see patients, not preclinical work.", "Fewer INDs mean fewer toxicology studies to buy."], "explanation": "Preclinical labs sit right where raised money turns into studies. They feel a slowdown first."}, "proReasoning": "Investors use preclinical CROs as an early gauge of biotech spending. They sit closest to the money.", "commonMistake": "Looking for funding effects only in biotech stocks.", "mentalModel": "Labs feel funding first."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup needs IND toxicology studies. You could build a lab or hire a CRO.", "prompt": "What fits a young biotech?", "options": ["Hire a CRO and spend cash on the drug", "Build a full animal lab of your own first", "Skip toxicology to save the money"], "correctIndex": 0, "consequences": ["That is how many biotechs buy preclinical studies.", "A lab ties up cash before you have a drug in trials.", "No IND, and no trial, without safety studies."], "explanation": "Buying studies from a CRO keeps cash for the drug itself. Building a lab rarely makes sense early."}, "proReasoning": "Founders rent capacity they need once and build only what makes them different. Safety studies are usually rented.", "commonMistake": "Building infrastructure a CRO already offers.", "mentalModel": "Rent the standard, build the edge."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend assumes drug companies test every new drug in their own labs.", "prompt": "What's more accurate?", "options": ["Universities do all the testing for free", "Many pay outside labs like Charles River", "The FDA runs the safety tests itself"], "correctIndex": 1, "consequences": ["Drugmakers pay for the studies their INDs need.", "Charles River's safety unit earned $2.40 billion doing this.", "The FDA reviews the results; it does not run the studies."], "explanation": "Much of the safety testing behind new drugs is bought from contract labs."}, "proReasoning": "Drug development is a supply chain. Many steps are done by specialist companies for hire.", "commonMistake": "Picturing one company doing every step.", "mentalModel": "Drugs have supply chains too."}}}$ml$::jsonb, ARRAY['handwritten-v1']::text[]),
($ml$72978c11-76e0-57b1-9bcc-a657113c40e0$ml$::uuid, $ml$biotech$ml$, 8, 3, $ml${"id": "biotech-d8-c3", "title": "Reading Charles River's signal", "lessonTitle": "Who runs the safety studies", "slot": 3, "type": "decide", "brief": {"headline": "Charles River's 2025 revenue fell 0.9% to $4.02 billion, and its discovery and safety unit fell 2.0%. Its chief executive said late-2025 bookings showed demand stabilizing.", "kicker": "Decide what a CRO's numbers say about biotech.", "fullText": "Charles River Laboratories reported 2025 revenue of $4.02 billion, down 0.9% from 2024. Its Discovery and Safety Assessment segment, which runs studies such as the toxicology work behind an IND, brought in $2.40 billion, down 2.0%.\n\nChief executive James Foster said fourth-quarter bookings showed the biopharmaceutical demand environment was stabilizing, and the company expected organic growth to return in the second half of 2026.\n\nWhen biotechs raise money, much of it pays outside labs for studies. When funding slows, lab bookings fall. You are reading the signal.", "sources": [{"url": "https://www.businesswire.com/news/home/20260218016453/en/Charles-River-Laboratories-Announces-Fourth-Quarter-and-Full-Year-2025-Results-and-Provides-2026-Guidance", "label": "Charles River Laboratories, fourth quarter and full year 2025 results, Feb 2026"}]}, "evidence": {"kind": "sortSignal", "prompt": "Does each fact point to weaker demand or to recovery?", "buckets": ["Weaker demand", "Recovery"], "items": [{"text": "Discovery and safety revenue fell 2.0%", "bucket": 0}, {"text": "Total revenue slipped 0.9%", "bucket": 0}, {"text": "Fourth-quarter bookings were stabilizing", "bucket": 1}, {"text": "Growth was expected back in late 2026", "bucket": 1}], "explanation": "The 2025 results show a soft year. The bookings and the outlook point to recovery."}, "numbers": {"kind": "numberSense", "prompt": "By what percent did Charles River's total revenue fall in 2025?", "min": 0, "max": 5, "value": 0.9, "unit": "%", "explanation": "Just 0.9%, while the safety unit fell 2.0%. A soft year, not a collapse."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're weighing a job offer at a preclinical CRO in early 2026.", "prompt": "What does the latest signal suggest?", "options": ["Booming demand and fast growth", "A business in permanent decline", "A soft 2025, with demand stabilizing"], "correctIndex": 2, "consequences": ["Revenue fell slightly in 2025.", "Bookings were stabilizing, and growth was expected back.", "Revenue dipped and bookings steadied late in the year."], "explanation": "The numbers show a dip and early signs of recovery. That's useful context for an offer."}, "proReasoning": "Read an employer's results before you join. A stabilizing business is a different bet from a booming or shrinking one.", "commonMistake": "Ignoring the company's own numbers when choosing a job.", "mentalModel": "Know where the cycle is."}, "invest": {"call": {"kind": "theCall", "situation": "You use CRO results to gauge biotech spending.", "prompt": "Which number leads, revenue or bookings?", "options": ["Bookings, since they become revenue later", "Revenue, since it is already earned", "Neither tells you anything useful"], "correctIndex": 0, "consequences": ["Stabilizing bookings hint at revenue to come.", "Revenue reflects work booked months ago.", "Both help, and bookings move first."], "explanation": "Bookings turn into revenue later. That's why Charles River's late-2025 bookings mattered."}, "proReasoning": "Investors watch CRO bookings as a leading gauge of biotech spending. Revenue confirms the trend later.", "commonMistake": "Reading last year's revenue as next year's demand.", "mentalModel": "Bookings lead revenue."}, "build_startup": {"call": {"kind": "theCall", "situation": "You sell lab equipment to preclinical CROs. Charles River says bookings are stabilizing.", "prompt": "When should you push sales hardest?", "options": ["Only once revenue is growing again", "As bookings recover and labs add work", "At the bottom, when budgets are frozen"], "correctIndex": 1, "consequences": ["By then, rivals may have the orders.", "Labs buy when they expect more studies to run.", "Frozen budgets rarely approve new purchases."], "explanation": "Bookings tell labs more work is coming. That is when they invest."}, "proReasoning": "Founders selling to labs time pushes to their customers' bookings. Demand upstream becomes budgets downstream.", "commonMistake": "Waiting for revenue to recover before selling.", "mentalModel": "Sell into your customer's recovery."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why Charles River's sales fell in 2025 when new drugs are still being made.", "prompt": "What's the likely reason?", "options": ["The FDA stopped requiring safety studies", "Drug development ended in 2025", "Biotechs had less money for studies"], "correctIndex": 2, "consequences": ["INDs still needed safety studies in 2025.", "Bookings were stabilizing by late 2025.", "When funding slows, lab bookings fall."], "explanation": "Lab sales follow biotech budgets. Slower funding meant fewer studies bought."}, "proReasoning": "Supplier sales rise and fall with their customers' budgets. The work continues, at a different pace.", "commonMistake": "Reading a sales dip as the end of an industry.", "mentalModel": "Budgets set the pace."}}}$ml$::jsonb, ARRAY['handwritten-v1']::text[]),
($ml$82bae137-e70f-5ba7-8a68-a288cff7e255$ml$::uuid, $ml$biotech$ml$, 9, 1, $ml${"id": "biotech-d9-c1", "title": "Fewer monkeys for antibody drugs", "lessonTitle": "The FDA rewrites the animal rules", "slot": 1, "type": "apply", "brief": {"headline": "On December 2, 2025, the FDA issued draft guidance saying six-month monkey toxicity studies for many antibody drugs can be reduced or eliminated. A typical antibody program can use more than 100 monkeys.", "kicker": "Apply the FDA's new standard to antibody safety testing.", "fullText": "The draft guidance covers monoclonal antibodies aimed at a single target. It says studies longer than three months in non-rodent species are generally unwarranted for judging chronic toxicity, if a weight-of-evidence risk assessment supports it. That assessment can draw on how the antibody works, published data on its target, and new approach methods such as computer models and organoids.\n\nA typical antibody program can involve more than 100 nonhuman primates, at about $50,000 each. FDA Commissioner Marty Makary said modern science offers more effective and humane ways to evaluate drug safety. The guidance is the first step in the plan the FDA laid out in April 2025.\n\nThe day 9 rule at work: the FDA decides what counts as proof, and companies test to that standard.", "sources": [{"url": "https://www.hklaw.com/en/insights/publications/2025/12/fda-publishes-new-draft-guidance-on-reducing-animal-testing", "label": "Holland & Knight, FDA publishes new draft guidance on reducing animal testing, Dec 2025"}, {"url": "https://www.dvm360.com/view/fda-issues-draft-guidance-to-reduce-six-month-nonhuman-primate-testing-for-monoclonal-antibodies", "label": "dvm360, FDA draft guidance to reduce six-month primate testing for antibodies, Dec 2025"}, {"url": "https://www.hklaw.com/en/insights/publications/2025/04/fda-announces-plan-to-phase-out-animal-testing-requirement", "label": "Holland & Knight, FDA announces plan to phase out animal testing requirement, Apr 2025"}]}, "evidence": {"kind": "spotFake", "prompt": "One of these is false about the December 2025 draft guidance. Tap it.", "statements": ["It covers antibodies aimed at a single target.", "Six-month monkey studies can be reduced or cut.", "It bans all animal testing for antibodies."], "fakeIndex": 2, "explanation": "It narrows when long monkey studies are needed. Animal studies that are still justified remain."}, "numbers": {"kind": "numberSense", "prompt": "At about $50,000 per monkey, what would 100 monkeys cost, in millions of dollars?", "min": 0, "max": 20, "value": 5, "unit": "M", "explanation": "About $5 million for one program, before the cost of running the studies."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're a toxicologist at an antibody company in December 2025.", "prompt": "Which skill grows in value?", "options": ["Avoiding contact with the FDA", "Building weight-of-evidence safety cases", "Running ever-longer monkey studies"], "correctIndex": 1, "consequences": ["The FDA encourages sponsors to discuss their plans.", "The guidance leans on risk assessments using several kinds of data.", "Studies past three months are now generally unwarranted."], "explanation": "The guidance rewards scientists who can assemble evidence from many sources into a safety case."}, "proReasoning": "When the standard of proof changes, the skills that meet it gain value. Toxicologists who can argue from evidence stand out.", "commonMistake": "Assuming the old study package stays the default.", "mentalModel": "Learn the new standard of proof."}, "invest": {"call": {"kind": "theCall", "situation": "You own shares in a lab company that earns heavily from long monkey studies.", "prompt": "How does the guidance affect your view?", "options": ["Nothing, since it is only a draft", "Demand for monkey studies will rise", "Some long monkey studies may disappear"], "correctIndex": 2, "consequences": ["Drafts signal where the FDA is heading.", "The guidance points the other way.", "Six-month studies for many antibodies can now be cut."], "explanation": "When the FDA narrows a requirement, revenue tied to it is at risk."}, "proReasoning": "Investors track FDA guidance as a demand signal for testing labs. A draft often shows the direction.", "commonMistake": "Dismissing draft guidance as noise.", "mentalModel": "FDA standards set testing demand."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup builds computer models that predict toxicity.", "prompt": "What does the guidance give you?", "options": ["A named role in FDA safety cases", "A guaranteed FDA contract", "Nothing, since only animals count"], "correctIndex": 0, "consequences": ["Computational models are listed as acceptable supporting evidence.", "Guidance opens a door; it does not buy your product.", "The guidance explicitly counts non-animal data."], "explanation": "The FDA named computer models and organoids as evidence sponsors can use."}, "proReasoning": "Founders point to the guidance language that names their method. It turns a nice-to-have into an accepted input.", "commonMistake": "Thinking regulatory acceptance means guaranteed sales.", "mentalModel": "An open door is not a sale."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks if the FDA just banned animal testing for drugs.", "prompt": "What's accurate?", "options": ["No, nothing has changed at all", "It may cut long monkey studies for some", "Yes, all animal tests are now banned"], "correctIndex": 1, "consequences": ["The guidance is a real change for antibodies.", "Six-month studies for many antibodies can be reduced.", "Justified animal studies are still used."], "explanation": "The change targets long monkey studies for certain antibodies. It is a step, not a ban."}, "proReasoning": "Big shifts in drug testing come in steps. Ask which drugs and which tests a change covers.", "commonMistake": "Hearing \"reduce\" and thinking \"ban.\"", "mentalModel": "Steps, not switches."}}}$ml$::jsonb, ARRAY['handwritten-v1']::text[]),
($ml$59773405-057e-53a2-8374-67c3c68e9660$ml$::uuid, $ml$biotech$ml$, 9, 2, $ml${"id": "biotech-d9-c2", "title": "A $2.4 billion business meets a new rule", "lessonTitle": "The FDA rewrites the animal rules", "slot": 2, "type": "connect", "brief": {"headline": "Charles River's discovery and safety unit earned $2.40 billion in 2025, running studies like IND toxicology work. In April 2025, the FDA said it wants animal studies to become the exception within three to five years.", "kicker": "Connect day 8 and day 9: when the FDA moves, the labs must follow.", "fullText": "On day 8 you saw Charles River's Discovery and Safety Assessment segment bring in $2.40 billion in 2025 from studies such as the toxicology work behind an IND. On day 9 you saw the FDA's April 2025 plan: phase out animal testing requirements, starting with monoclonal antibodies, using approaches such as computer models of toxicity and organoids, and make animal studies the exception within three to five years.\n\nPut them together. Companies run the tests the FDA will accept. When the FDA changes its standard, labs built on the old one must adapt, and builders of the new methods gain a market.", "sources": [{"url": "https://www.businesswire.com/news/home/20260218016453/en/Charles-River-Laboratories-Announces-Fourth-Quarter-and-Full-Year-2025-Results-and-Provides-2026-Guidance", "label": "Charles River Laboratories, fourth quarter and full year 2025 results, Feb 2026"}, {"url": "https://www.hklaw.com/en/insights/publications/2025/04/fda-announces-plan-to-phase-out-animal-testing-requirement", "label": "Holland & Knight, FDA announces plan to phase out animal testing requirement, Apr 2025"}]}, "evidence": {"kind": "faceOff", "prompt": "If animal studies become the exception, who faces more pressure to change?", "left": {"name": "A lab built on animal safety studies", "note": "Earns from toxicology work behind INDs"}, "right": {"name": "A maker of organoid test systems", "note": "Sells a method the FDA named"}, "correctIndex": 0, "explanation": "The lab must shift its offer as demand moves. The organoid maker is selling what the FDA now invites."}, "numbers": {"kind": "numberSense", "prompt": "The FDA aims to make animal studies the exception within how many years, at most?", "min": 0, "max": 12, "value": 5, "unit": "years", "explanation": "Three to five years from April 2025. Fast for an industry built on animal studies."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You work in a CRO's animal toxicology unit in 2025.", "prompt": "What's your smartest career move?", "options": ["Assume nothing will change for years", "Leave toxicology for another field", "Learn the methods the FDA now accepts"], "correctIndex": 2, "consequences": ["The FDA set a three to five year horizon.", "Safety testing still matters; its methods are changing.", "The FDA invited data from these methods right away."], "explanation": "The work is shifting, not ending. Skills in the new methods keep you in demand."}, "proReasoning": "When regulators change the standard, people who learn the new tools early become the experts. It is a career opening.", "commonMistake": "Waiting for the change to arrive before adapting.", "mentalModel": "Move with the standard."}, "invest": {"call": {"kind": "theCall", "situation": "A CRO earns most of its revenue from animal safety studies.", "prompt": "What's the key question about its future?", "options": ["Can it shift to the new accepted methods?", "Does it house more animals than rivals?", "Is its share price near a record high?"], "correctIndex": 0, "consequences": ["Labs built on animal work must adapt as the standard moves.", "More animals could become a burden, not an edge.", "Price history says nothing about the shift."], "explanation": "The FDA's plan changes what clients will pay for. The question is whether the lab can follow."}, "proReasoning": "Investors ask whether a business can survive a change in the rules it depends on. Adaptability becomes the thesis.", "commonMistake": "Valuing a lab on yesterday's standard.", "mentalModel": "Ask who must adapt."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup sells organoid toxicity tests. Big CROs could be customers or rivals.", "prompt": "What's the best first pitch?", "options": ["Wait until animal tests are banned", "Help CROs adapt as animal work shrinks", "Tell drugmakers to stop using CROs"], "correctIndex": 1, "consequences": ["The plan makes animal studies the exception, not banned.", "Labs built on animal work must adapt, which makes them buyers.", "Drugmakers still rely on CROs for safety studies."], "explanation": "The labs under pressure need new methods. That makes them a natural first customer."}, "proReasoning": "Founders often sell to the incumbent under pressure before competing with it. Their need is your opening.", "commonMistake": "Treating every incumbent as an enemy.", "mentalModel": "The incumbent's problem is your market."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why a lab company would care about an FDA announcement.", "prompt": "What's the reason?", "options": ["The FDA owns the lab company", "Lab companies only sell to the FDA", "The FDA sets the tests customers run"], "correctIndex": 2, "consequences": ["The FDA regulates drugs; it does not own labs.", "Labs sell to drugmakers, who answer to the FDA.", "Companies run the tests the FDA will accept."], "explanation": "Drugmakers buy the studies the FDA requires. Change the requirement and you change the labs' business."}, "proReasoning": "In regulated industries, the regulator shapes demand. Follow its rules to follow the money.", "commonMistake": "Thinking regulators only affect the companies they directly approve.", "mentalModel": "The regulator shapes demand."}}}$ml$::jsonb, ARRAY['handwritten-v1']::text[]),
($ml$a8581465-b9e3-5bc2-8c2b-e80e71ac10c6$ml$::uuid, $ml$biotech$ml$, 9, 3, $ml${"id": "biotech-d9-c3", "title": "Animal study or new method?", "lessonTitle": "The FDA rewrites the animal rules", "slot": 3, "type": "decide", "brief": {"headline": "In April 2025, the FDA announced a plan to phase out animal testing requirements, starting with monoclonal antibodies. It encouraged companies to submit data from non-animal methods right away.", "kicker": "Decide how to plan your next safety package.", "fullText": "On April 10, 2025, the FDA announced a plan to phase out animal testing requirements for monoclonal antibodies and other drugs, using approaches such as AI-based computer models of toxicity and organoid toxicity testing. It aims to make animal studies the exception rather than the norm within three to five years. The FDA Modernization Act 2.0, passed in late 2022, had already authorized non-animal alternatives for INDs.\n\nYou run preclinical work at an antibody biotech planning its next IND.", "sources": [{"url": "https://www.hklaw.com/en/insights/publications/2025/04/fda-announces-plan-to-phase-out-animal-testing-requirement", "label": "Holland & Knight, FDA announces plan to phase out animal testing requirement, Apr 2025"}]}, "evidence": {"kind": "sortSignal", "prompt": "Does each plan fit the FDA plan or misread it?", "buckets": ["Fits the plan", "Misreads it"], "items": [{"text": "Add organoid toxicity data to the IND", "bucket": 0}, {"text": "Use computer models of toxicity", "bucket": 0}, {"text": "Expect animal studies to become the exception", "bucket": 0}, {"text": "Assume animal tests were banned in 2025", "bucket": 1}, {"text": "Ignore new methods until the 2030s", "bucket": 1}], "explanation": "The plan invites new data now and phases animals down over years. It is neither a ban nor a distant idea."}, "numbers": {"kind": "numberSense", "prompt": "At the soonest, in how many years does the FDA aim to make animal studies the exception?", "min": 0, "max": 10, "value": 3, "unit": "years", "explanation": "Three years at the soonest, five at the latest, from April 2025."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "Your boss asks how the FDA plan affects your next antibody IND.", "prompt": "What do you say?", "options": ["We can submit non-animal data now", "We must stop all animal work today", "Nothing changes until the 2030s"], "correctIndex": 0, "consequences": ["The FDA encouraged that data right away.", "The plan phases animal studies down; it is not a ban.", "The plan runs on a three to five year horizon."], "explanation": "The FDA asked for non-animal data immediately, starting with antibodies like yours."}, "proReasoning": "Give your team a precise reading of a new rule: what changes now, what changes later. Precision builds trust.", "commonMistake": "Overreacting or underreacting to a regulatory shift.", "mentalModel": "What changes now, what changes later."}, "invest": {"call": {"kind": "theCall", "situation": "A biotech claims the FDA plan wipes out its preclinical costs.", "prompt": "How do you read the claim?", "options": ["Irrelevant; the plan skips antibodies", "Overstated; the shift is phased over years", "Accurate; animal tests ended in 2025"], "correctIndex": 1, "consequences": ["Antibodies were the first drugs the plan named.", "The FDA aims for three to five years, not overnight.", "The plan made animal studies the goal to reduce, not end."], "explanation": "The plan is real but gradual. Costs may fall over time, not vanish at once."}, "proReasoning": "Investors check company claims against the actual rule. Gradual changes rarely deliver instant savings.", "commonMistake": "Taking a company's reading of a new rule on trust.", "mentalModel": "Check the claim against the rule."}, "build_startup": {"call": {"kind": "theCall", "situation": "You are founding a non-animal safety testing company in 2025.", "prompt": "Which drugs should you target first?", "options": ["Vaccines, which the plan named first", "Generics, which need the most tests", "Monoclonal antibodies, where the FDA began"], "correctIndex": 2, "consequences": ["The plan named monoclonal antibodies first, not vaccines.", "Generics skip the original trials and studies.", "The plan started with monoclonal antibodies."], "explanation": "Start where the FDA started. Antibody developers are the first to need accepted alternatives."}, "proReasoning": "Founders enter where the regulator opens the door first. Demand forms there before anywhere else.", "commonMistake": "Targeting a market the rule change has not reached yet.", "mentalModel": "Start where the door opened."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why the FDA would change rules that have been used for decades.", "prompt": "What's a fair answer?", "options": ["Newer methods like organoids may stand in", "Animals were never used before 2025", "Congress banned animal testing"], "correctIndex": 0, "consequences": ["The FDA named computer models and organoids as options.", "Animal studies had long been standard.", "A 2022 law allowed alternatives; it did not ban animals."], "explanation": "The FDA thinks newer methods such as organoids and computer models can replace many animal tests."}, "proReasoning": "Rules change when new tools give regulators other ways to get the proof they need.", "commonMistake": "Assuming rule changes are only about cost.", "mentalModel": "New tools, new proof."}}}$ml$::jsonb, ARRAY['handwritten-v1']::text[]),
($ml$c0dba73e-0c3f-5b9c-9370-b133bb130200$ml$::uuid, $ml$biotech$ml$, 10, 1, $ml${"id": "biotech-d10-c1", "title": "When 60% of the monkeys stopped", "lessonTitle": "What a lab monkey costs", "slot": 1, "type": "apply", "brief": {"headline": "In February 2023, Charles River suspended shipments of lab monkeys from Cambodia after a US Justice Department subpoena. Cambodia had supplied roughly 60% of the monkeys used in US drug research.", "kicker": "Apply supply and demand to the lab monkey market.", "fullText": "Charles River received the subpoena on February 17, 2023, as part of a federal investigation into the Cambodian supply chain. Months earlier, the Justice Department had charged eight people, including two Cambodian officials, with smuggling wild long-tailed macaques into the US.\n\nCharles River voluntarily suspended future Cambodian shipments until it and federal wildlife officials agreed on procedures to ensure imported animals were bred for research. Its chief executive, James Foster, said Cambodian monkeys made up roughly 60% of those supplied to the US, and that no global source could replace them. Demand had been high, driven by growth in biologic drug development.\n\nDay 10 showed demand pushing monkey prices up in China. Here the squeeze came from supply.", "sources": [{"url": "https://www.boston.com/news/business/2023/02/23/massachusetts-charles-river-laboratories-subpoena-monkey-smuggling-investigation/", "label": "Boston.com, Charles River subpoenaed in monkey smuggling investigation, Feb 2023"}, {"url": "https://www.statnews.com/pharmalot/2023/02/22/charles-river-monkey-macaques-research-cambodia/", "label": "STAT, Charles River suspends Cambodian monkey shipments, Feb 2023"}, {"url": "https://www.scmp.com/business/china-business/article/3343819/chinas-biotech-boom-sends-price-lab-monkeys-drug-tests-climbing", "label": "South China Morning Post, China's biotech boom sends price of lab monkeys climbing, Feb 2026"}]}, "evidence": {"kind": "buildChain", "prompt": "Follow how a supply shock reaches drug testing.", "steps": ["Investigators probe the Cambodian supply chain", "Charles River receives a subpoena", "It suspends Cambodian monkey shipments", "About 60% of US supply is in question", "Safety studies face a supply squeeze"], "explanation": "One source supplied most of the monkeys. When it stopped, every study needing them felt it."}, "numbers": {"kind": "numberSense", "prompt": "Roughly what percent of the monkeys used in US drug research came from Cambodia?", "min": 0, "max": 100, "value": 60, "unit": "%", "explanation": "About 60%, with no other source ready to replace it."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You plan safety studies at a biotech in March 2023. Your IND needs monkey toxicology work.", "prompt": "What do you do?", "options": ["Assume the delay will clear in a week", "Drop toxicology from the IND", "Lock in study slots and add schedule buffer"], "correctIndex": 2, "consequences": ["No other source could quickly replace Cambodia.", "There is no IND without its safety studies.", "With supply cut, early bookings protect your timeline."], "explanation": "When supply shrinks, secure what you need early and plan for delay."}, "proReasoning": "Planners react to supply shocks by securing capacity and padding timelines. Optimism is not a plan.", "commonMistake": "Assuming a supply shock will pass quickly.", "mentalModel": "Secure supply, pad the schedule."}, "invest": {"call": {"kind": "theCall", "situation": "Charles River has just suspended Cambodian monkey shipments.", "prompt": "What risk do you check across your biotech holdings?", "options": ["Delays to safety studies before INDs", "Higher prices for approved drugs", "Lower FDA fees for new filings"], "correctIndex": 0, "consequences": ["Fewer monkeys can push back the studies an IND needs.", "Approved drugs no longer need these studies.", "FDA fees have nothing to do with monkey supply."], "explanation": "Companies near an IND are the most exposed. Their safety studies may slip."}, "proReasoning": "Investors trace a supply shock to the companies whose next milestone depends on it. Preclinical biotechs come first.", "commonMistake": "Treating a lab supply problem as irrelevant to drug companies.", "mentalModel": "Find whose milestone depends on it."}, "build_startup": {"call": {"kind": "theCall", "situation": "You run a startup offering non-animal toxicity tests in 2023.", "prompt": "How does the shortage change your pitch?", "options": ["Wait for the shortage to end", "Offer a way around the monkey squeeze", "Promise to supply monkeys yourself"], "correctIndex": 1, "consequences": ["The urgency is highest during the shortage.", "A 2022 law already allowed non-animal data in INDs.", "That is a different and harder business."], "explanation": "A shortage makes alternatives urgent. Pitch while customers feel the pain."}, "proReasoning": "Founders pitch hardest when the old way breaks. A supply shock can do more for adoption than any feature.", "commonMistake": "Waiting for calm when the crisis creates demand.", "mentalModel": "Pitch when the old way breaks."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks how a smuggling case in Cambodia could slow new medicines in the US.", "prompt": "What's the link?", "options": ["Cambodia must approve new US drugs", "The drugs themselves are made in Cambodia", "Most US lab monkeys came from Cambodia"], "correctIndex": 2, "consequences": ["The FDA approves US drugs.", "The link is the test animals, not the factories.", "About 60% of the supply was suddenly in doubt."], "explanation": "Safety studies need monkeys, and most came from one country."}, "proReasoning": "Long supply chains hide single points of failure. One country can matter a lot.", "commonMistake": "Thinking drug development depends only on science.", "mentalModel": "Find the single source."}}}$ml$::jsonb, ARRAY['handwritten-v1']::text[]),
($ml$801553b3-bf08-5edb-aaf9-624208429b22$ml$::uuid, $ml$biotech$ml$, 10, 2, $ml${"id": "biotech-d10-c2", "title": "Doubled prices, open doors", "lessonTitle": "What a lab monkey costs", "slot": 2, "type": "connect", "brief": {"headline": "Lab monkey prices in China doubled over five years, to about 140,000 yuan each by early 2026. Meanwhile, the FDA had begun inviting non-animal data and planned to make animal studies the exception.", "kicker": "Connect day 9 and day 10: rising costs meet a new rule.", "fullText": "On day 10 you saw monkey prices in China reach about 140,000 yuan, or about $20,260, each in early 2026, after doubling over five years. One Shanghai institute budgeted 62 million yuan for 450 cynomolgus macaques. The driver was a record number of drug candidates entering early testing.\n\nOn day 9 you saw the FDA's April 2025 plan to phase out animal testing requirements, starting with monoclonal antibodies, and to make animal studies the exception within three to five years.\n\nPut them together. Costlier animals and an FDA open to other methods push in the same direction.", "sources": [{"url": "https://www.scmp.com/business/china-business/article/3343819/chinas-biotech-boom-sends-price-lab-monkeys-drug-tests-climbing", "label": "South China Morning Post, China's biotech boom sends price of lab monkeys climbing, Feb 2026"}, {"url": "https://www.hklaw.com/en/insights/publications/2025/04/fda-announces-plan-to-phase-out-animal-testing-requirement", "label": "Holland & Knight, FDA announces plan to phase out animal testing requirement, Apr 2025"}]}, "evidence": {"kind": "spotFake", "prompt": "One of these is false. Tap it.", "statements": ["One Shanghai institute budgeted 62 million yuan for 450 monkeys.", "The FDA plan started with monoclonal antibodies.", "Monkey prices in China fell as the FDA plan took hold."], "fakeIndex": 2, "explanation": "Prices doubled over five years, reaching about 140,000 yuan in early 2026."}, "numbers": {"kind": "numberSense", "prompt": "62 million yuan for 450 monkeys: about how much is each, in thousands of yuan?", "min": 0, "max": 320, "value": 138, "unit": "K", "explanation": "About 137,800 yuan each, close to the 140,000 market price."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're a preclinical lead at a biotech in 2026, facing monkey costs of 140,000 yuan each.", "prompt": "What's your best plan?", "options": ["Use FDA-accepted non-animal data where it fits", "Order twice the monkeys before prices rise", "Delay every IND until prices fall"], "correctIndex": 0, "consequences": ["The FDA invited such data, starting with antibodies.", "Stockpiling at record prices ties up cash.", "Prices doubled in five years; waiting may not help."], "explanation": "Rising costs and the FDA plan both reward using alternatives where they are accepted."}, "proReasoning": "Strong preclinical leads match the method to the drug and the rule. Cost and regulation now point the same way.", "commonMistake": "Treating rising animal costs as a fixed fact of life.", "mentalModel": "Let cost and rules guide the method."}, "invest": {"call": {"kind": "theCall", "situation": "A lab-monkey breeder's profits are soaring along with prices.", "prompt": "What longer-term risk do you weigh?", "options": ["Monkeys getting cheaper to breed", "Regulators accepting non-animal methods", "Too few biotechs testing new drugs"], "correctIndex": 1, "consequences": ["That would lower prices, not threaten demand.", "The FDA aims to make animal studies the exception.", "Record numbers of candidates are entering testing."], "explanation": "High prices today can meet falling demand tomorrow if the FDA shifts the standard."}, "proReasoning": "Investors ask whether a boom has a regulatory ceiling. Here the FDA is building one.", "commonMistake": "Extrapolating record prices without checking the rules.", "mentalModel": "Booms can have ceilings."}, "build_startup": {"call": {"kind": "theCall", "situation": "You're pitching an organoid testing startup to investors in 2026.", "prompt": "What's your strongest why-now?", "options": ["Organoids were only invented last year", "Animal tests are now illegal in the US", "Costlier monkeys, and an FDA opening up"], "correctIndex": 2, "consequences": ["Organoids are not brand new; the rules are.", "Animal studies are being reduced, not outlawed.", "Rising costs and new rules create demand together."], "explanation": "The timing matters: costs went up just as the FDA started accepting alternatives."}, "proReasoning": "A good why-now ties two forces together. Cost pressure plus regulatory change is hard to ignore.", "commonMistake": "Pitching the technology without the timing.", "mentalModel": "Two forces make a why-now."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why anyone would replace monkeys in drug tests.", "prompt": "What's the best answer?", "options": ["Costs rose, and the FDA takes other data", "Monkeys give no useful safety data at all", "A 2025 law banned their use in testing"], "correctIndex": 0, "consequences": ["Prices doubled, and the FDA invited non-animal methods.", "Monkey studies still inform many safety reviews.", "No ban; the FDA plans to make them the exception."], "explanation": "Cost and a changing FDA standard both favor alternatives where they work."}, "proReasoning": "Change often comes when cost and rules line up. Neither alone moves an industry as fast.", "commonMistake": "Assuming one reason explains a shift.", "mentalModel": "Look for forces that line up."}}}$ml$::jsonb, ARRAY['handwritten-v1']::text[]),
($ml$64f1a27a-cf52-56a6-bc18-d2958717de3a$ml$::uuid, $ml$biotech$ml$, 10, 3, $ml${"id": "biotech-d10-c3", "title": "Budgeting for monkeys", "lessonTitle": "What a lab monkey costs", "slot": 3, "type": "decide", "brief": {"headline": "A Shanghai institute budgeted 62 million yuan for 450 lab monkeys in early 2026, roughly 137,800 yuan each. Official records showed prices doubling over five years.", "kicker": "Decide how a costlier monkey changes your plans.", "fullText": "In February 2026, the South China Morning Post reported lab monkey prices in China of about 140,000 yuan, or about $20,260, each. A Shanghai Institute of Materia Medica tender budgeted 62 million yuan for 450 cynomolgus macaques.\n\nProcurement records showed prices doubling over five years, driven by licensing deals between Chinese biotechs and global drugmakers and a revival in fundraising that pushed a record number of drug candidates into early testing.\n\nYou run a biotech planning several INDs. More drugs in early testing means more demand for test animals, and higher costs for everyone.", "sources": [{"url": "https://www.scmp.com/business/china-business/article/3343819/chinas-biotech-boom-sends-price-lab-monkeys-drug-tests-climbing", "label": "South China Morning Post, China's biotech boom sends price of lab monkeys climbing, Feb 2026"}]}, "evidence": {"kind": "faceOff", "prompt": "Which biotech is hit harder by rising monkey prices?", "left": {"name": "One planning several new INDs", "note": "Each needs its own safety studies"}, "right": {"name": "One whose drug is already in Phase 2", "note": "Its preclinical safety work is done"}, "correctIndex": 0, "explanation": "Safety studies come before the IND. A company with several INDs ahead pays the higher price for each."}, "numbers": {"kind": "numberSense", "prompt": "At about $20,000 per monkey, what do 450 monkeys cost, in millions of dollars?", "min": 0, "max": 30, "value": 9, "unit": "M", "explanation": "About $9 million, double what the same order cost five years earlier."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're a budget analyst at a biotech. The plan still uses monkey prices from five years ago.", "prompt": "What do you flag?", "options": ["Animal prices don't affect safety budgets", "Prices doubled, so safety budgets must rise", "Prices fell, so there are savings"], "correctIndex": 1, "consequences": ["Monkeys are a direct cost of many safety studies.", "Every IND now costs more in preclinical testing.", "Records show prices doubling, not falling."], "explanation": "Old prices understate the cost of every safety package. Update them before the money runs short."}, "proReasoning": "Analysts who catch outdated inputs save projects from surprise shortfalls. Doubling prices are exactly that kind of input.", "commonMistake": "Rolling last cycle's cost assumptions forward.", "mentalModel": "Refresh the inputs."}, "invest": {"call": {"kind": "theCall", "situation": "A biotech plans four INDs next year on the same preclinical budget it used five years ago for two.", "prompt": "What do you question?", "options": ["Whether its office lease is too long", "Whether it has a famous chief executive", "Whether it priced in doubled monkey costs"], "correctIndex": 2, "consequences": ["Leases matter less than the cost of the studies.", "Fame does not pay for safety studies.", "Twice the INDs at twice the price is far more cash."], "explanation": "Testing costs eat cash. A flat budget against doubled prices signals a shortfall."}, "proReasoning": "Investors check how much cash preclinical work burns and whether plans reflect current prices.", "commonMistake": "Accepting an old budget for new plans.", "mentalModel": "Price the plan at today's costs."}, "build_startup": {"call": {"kind": "theCall", "situation": "You're choosing your startup's first program. One needs heavy monkey testing; the other far less.", "prompt": "How should costs weigh in?", "options": ["Count the monkey bill in each program's cost", "Ignore it, since testing costs are small", "Pick the monkey-heavy one to stand out"], "correctIndex": 0, "consequences": ["At about $20,000 each, monkeys can shift the budget.", "450 monkeys cost about $9 million.", "Standing out does not pay for the studies."], "explanation": "Testing needs differ by program. At current prices, they belong in the choice."}, "proReasoning": "Founders cost each program end to end before choosing. Preclinical testing is no longer a rounding error.", "commonMistake": "Choosing a program on science alone when costs differ a lot.", "mentalModel": "Cost each path before choosing."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks how a lab monkey can cost as much as a car.", "prompt": "Why so pricey?", "options": ["The FDA sets the price of each monkey", "Booming demand from new drug candidates", "They are flown around the world first class"], "correctIndex": 1, "consequences": ["Prices come from supply and demand, not the FDA.", "A record number of candidates entered early testing.", "Shipping is not what doubled prices."], "explanation": "More drugs entering early testing means more demand for test animals, so prices rose."}, "proReasoning": "Prices rise when demand outruns supply. Drug pipelines create demand for everything that tests them.", "commonMistake": "Looking for a single culprit behind a price rise.", "mentalModel": "Busy pipelines raise testing costs."}}}$ml$::jsonb, ARRAY['handwritten-v1']::text[]),
($ml$3d7b8b80-cf4c-54db-bd30-42d4ba4bfacd$ml$::uuid, $ml$biotech$ml$, 11, 1, $ml${"id": "biotech-d11-c1", "title": "A liver signal stops a gene editor", "lessonTitle": "When the FDA says not yet", "slot": 1, "type": "apply", "brief": {"headline": "In October 2025, the FDA put both Phase 3 trials of Intellia's gene editing therapy nex-z on clinical hold after a patient had severe liver test results. Both holds lifted in early 2026, with new safeguards.", "kicker": "Apply the clinical hold to a late-stage gene editor.", "fullText": "Nex-z, developed by Intellia with Regeneron, uses CRISPR to switch off the TTR gene in people with transthyretin amyloidosis. On October 29, 2025, the FDA placed the MAGNITUDE and MAGNITUDE-2 trials on hold after a MAGNITUDE patient had grade 4 liver transaminase elevations and raised bilirubin. That patient, a man in his 80s, died in November; Intellia later said the death was due to infection, not the liver event. Fewer than 1% of the more than 450 MAGNITUDE patients dosed had grade 4 liver elevations.\n\nThe FDA lifted the MAGNITUDE-2 hold in January 2026, after Intellia agreed to protocol changes including closer liver monitoring. The MAGNITUDE hold was lifted by early March, with extra conditions: steroid guidance if liver enzymes rose after dosing, and exclusion of patients with certain liver problems or unstable heart disease.\n\nA hold is a pause with questions attached. The company answers them with data and changes, and the trial can resume.", "sources": [{"url": "https://www.neurologylive.com/view/fda-lifts-clinical-hold-intellia-trial-gene-editing-therapy-nex-z-attrv-pn-places-holds-regenxbio-mps-trials", "label": "NeurologyLive, FDA lifts hold on Intellia's MAGNITUDE-2 trial, Jan 2026"}, {"url": "https://www.clinicaltrialsarena.com/news/fda-releases-hold-on-second-of-intellias-attr-cm-gene-therapy-trials/", "label": "Clinical Trials Arena, FDA releases hold on second of Intellia's trials, Mar 2026"}, {"url": "https://www.fiercebiotech.com/biotech/verves-base-editing-hold-lifted-starting-thaw-regulatory-blockade-sent-peers-ex-us", "label": "Fierce Biotech, Verve's base editing hold lifted, 2023"}]}, "evidence": {"kind": "buildChain", "prompt": "Put the nex-z hold in order.", "steps": ["A patient shows severe liver test results", "The FDA holds both Phase 3 trials", "Intellia agrees to closer liver monitoring", "The MAGNITUDE-2 hold lifts in January 2026", "The MAGNITUDE hold lifts with extra conditions"], "explanation": "A safety signal, a pause, answers and changes, then a restart with safeguards."}, "numbers": {"kind": "numberSense", "prompt": "More than how many MAGNITUDE patients had been dosed when the hold came?", "min": 0, "max": 1000, "value": 450, "unit": "patients", "explanation": "More than 450, and fewer than 1% had grade 4 liver elevations."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You join Intellia's regulatory team the week of the hold.", "prompt": "What's the team's main task?", "options": ["Answer the FDA with data and fixes", "Wait quietly until the FDA lifts it", "Keep dosing new patients in the US"], "correctIndex": 0, "consequences": ["Closer liver monitoring and new exclusions helped lift the holds.", "Holds lift when the FDA's concerns are answered.", "A hold blocks the trial until the questions are answered."], "explanation": "The FDA lifted the holds after Intellia changed the protocols to manage the liver risk."}, "proReasoning": "Regulatory teams treat a hold as a list of questions to answer fast. Concrete protocol changes are what move the FDA.", "commonMistake": "Treating a hold as a verdict instead of a request.", "mentalModel": "A hold is a question; answer it."}, "invest": {"call": {"kind": "theCall", "situation": "A gene editing company's Phase 3 trials are put on hold after one severe liver case.", "prompt": "What's the most useful question?", "options": ["Will the stock recover by Friday?", "How rare is it, and can it be managed?", "Is the company finished for good?"], "correctIndex": 1, "consequences": ["Short-term moves say little about the program.", "Under 1% had grade 4 elevations, and monitoring helped lift the holds.", "Both holds lifted within about five months."], "explanation": "How often a risk occurs, and whether it can be monitored, decides whether a hold ends."}, "proReasoning": "Investors price hold risk by the frequency and manageability of the safety signal, not the headline.", "commonMistake": "Treating every hold as fatal.", "mentalModel": "Frequency and fixability."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your gene therapy startup is designing its first trial.", "prompt": "What does nex-z teach about safety plans?", "options": ["Leave safety plans until problems appear", "Enroll every patient who applies", "Build in liver monitoring and clear exclusions"], "correctIndex": 2, "consequences": ["Adding them after a hold costs months.", "Exclusions protect higher-risk patients.", "Those were the safeguards that got nex-z moving again."], "explanation": "Safeguards added before a hold are cheaper than safeguards added after one."}, "proReasoning": "Founders design trials with the likely safety questions already answered. It makes a hold less likely and shorter.", "commonMistake": "Treating safety monitoring as a cost to trim.", "mentalModel": "Answer the questions before they are asked."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend reads that the FDA \"stopped\" a CRISPR therapy and thinks it is dead.", "prompt": "What's more accurate?", "options": ["Paused, then resumed with safeguards", "It was banned by the FDA for good", "It was approved for sale to patients"], "correctIndex": 0, "consequences": ["Both trials restarted in early 2026.", "The holds lifted after protocol changes.", "It is still in Phase 3 trials."], "explanation": "A clinical hold pauses a trial until the FDA is satisfied. Many resume."}, "proReasoning": "Pause is not stop. Ask what the FDA wanted and whether the company delivered it.", "commonMistake": "Reading every hold as the end of a drug.", "mentalModel": "Paused, not stopped."}}}$ml$::jsonb, ARRAY['handwritten-v1']::text[]),
($ml$0ae266d6-0e82-5e19-8e3b-8a74cbe76e05$ml$::uuid, $ml$biotech$ml$, 11, 2, $ml${"id": "biotech-d11-c2", "title": "The 30 days, and what came after", "lessonTitle": "When the FDA says not yet", "slot": 2, "type": "connect", "brief": {"headline": "The FDA has 30 days to object to an IND. In November 2022, it put Verve's gene editing drug on clinical hold instead. The US hold lasted nearly a year.", "kicker": "Connect day 7 and day 11: the 30-day review can end in a hold.", "fullText": "On day 7 you saw the IND's parts and its clock: animal safety studies, manufacturing details and clinical protocols, with 30 days for the FDA to object. If it finds a problem, it can place a clinical hold.\n\nOn day 11 you saw that happen. In November 2022, the FDA held Verve's IND for VERVE-101, a base editing treatment for an inherited form of high cholesterol. It asked whether the edits could pass to patients' children, for more preclinical data on how human and non-human cells differ in response, and for off-target analyses in other cell types. Verve kept enrolling in New Zealand and the UK, and the US hold was lifted after nearly a year.", "sources": [{"url": "https://en.wikipedia.org/wiki/Investigational_New_Drug", "label": "Investigational New Drug application, overview"}, {"url": "https://www.fiercebiotech.com/biotech/verves-base-editing-hold-lifted-starting-thaw-regulatory-blockade-sent-peers-ex-us", "label": "Fierce Biotech, Verve's base editing hold lifted, 2023"}]}, "evidence": {"kind": "multipleChoice", "prompt": "Which part of the IND did the FDA's questions to Verve mainly target?", "options": ["The preclinical safety data", "The manufacturing batch records", "The investigators' qualifications"], "correctIndex": 0, "explanation": "Germline risk, human versus animal cell response and off-target effects are all preclinical safety questions."}, "numbers": {"kind": "numberSense", "prompt": "Verve's US hold lasted nearly how many months?", "min": 0, "max": 36, "value": 12, "unit": "months", "explanation": "Nearly a year, against a 30-day review window."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You are preparing an IND for a new kind of gene editor.", "prompt": "Where should you put extra effort?", "options": ["Fewer animal studies to save time", "Preclinical answers on the novel risks", "A shorter summary of the protocol"], "correctIndex": 1, "consequences": ["Thinner safety data invites the questions Verve got.", "Verve's hold asked for more preclinical data on novel risks.", "Brevity does not answer safety questions."], "explanation": "New kinds of drugs draw new questions. Answer them in the IND before the FDA asks."}, "proReasoning": "Regulatory scientists anticipate the questions a novel product raises. The best IND answers them up front.", "commonMistake": "Filing a novel product as if it were routine.", "mentalModel": "New method, new questions."}, "invest": {"call": {"kind": "theCall", "situation": "A biotech with a new kind of therapy files its IND. You are timing its first US trial.", "prompt": "What should you allow for?", "options": ["Trials starting exactly 30 days later", "Approval within a year", "A possible hold and months of delay"], "correctIndex": 2, "consequences": ["30 days is the best case, not a promise.", "Approval is years away even without a hold.", "Verve's US hold lasted nearly a year."], "explanation": "Novel therapies often face more FDA questions before trials. Build that into the timeline."}, "proReasoning": "Investors add hold risk to timelines for new modalities. The 30-day window is the floor, not the forecast.", "commonMistake": "Assuming every IND clears in 30 days.", "mentalModel": "Novel means more questions."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup's US trial is on hold. Regulators in other countries have allowed testing.", "prompt": "What can you do?", "options": ["Test abroad while answering the FDA", "Keep dosing US patients anyway", "Abandon the drug and start over"], "correctIndex": 0, "consequences": ["Verve enrolled in New Zealand and the UK during its hold.", "A US hold bars dosing until it is lifted.", "A hold is a request, not a final no."], "explanation": "Verve kept generating data abroad while it answered the FDA."}, "proReasoning": "Founders keep programs moving across countries when one regulator pauses. Data from abroad can help answer the hold.", "commonMistake": "Letting one hold freeze the whole program.", "mentalModel": "Paused here, moving there."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks how the FDA can stop a trial before anyone gets a dose.", "prompt": "What's the answer?", "options": ["It owns the hospitals that run trials", "Its 30-day IND review lets it place a hold", "It must approve each patient by name"], "correctIndex": 1, "consequences": ["The FDA regulates trials; it does not own hospitals.", "If it finds a problem, it can hold the IND.", "The FDA reviews the plan, not each patient."], "explanation": "Every IND gets a 30-day review. A clinical hold can stop the trial before it starts."}, "proReasoning": "The FDA guards the gate before the first dose. That is where many safety questions get asked.", "commonMistake": "Thinking the FDA only acts after problems appear.", "mentalModel": "The gate comes before the dose."}}}$ml$::jsonb, ARRAY['handwritten-v1']::text[]),
($ml$cf53f663-5793-5809-9595-c9a2e04c8c8c$ml$::uuid, $ml$biotech$ml$, 11, 3, $ml${"id": "biotech-d11-c3", "title": "Answering a hold letter", "lessonTitle": "When the FDA says not yet", "slot": 3, "type": "decide", "brief": {"headline": "The FDA's hold on Verve asked three things: could the edits pass to patients' children, do human and animal cells respond differently, and what are the off-target effects in other cells?", "kicker": "Decide how to answer a clinical hold.", "fullText": "In November 2022, the FDA placed a clinical hold on Verve Therapeutics' IND for VERVE-101, a base editing treatment for an inherited form of high cholesterol. It asked whether the edits could be passed to patients' children, for more preclinical data on potency differences between human and non-human cells, and for off-target analyses in other cell types.\n\nVerve kept enrolling patients in New Zealand and the UK, and the US hold was lifted after nearly a year. A hold blocks trials until the FDA's questions are answered, and months of delay burn cash.\n\nYou run a biotech that has just received a hold letter.", "sources": [{"url": "https://www.fiercebiotech.com/biotech/verves-base-editing-hold-lifted-starting-thaw-regulatory-blockade-sent-peers-ex-us", "label": "Fierce Biotech, Verve's base editing hold lifted, 2023"}, {"url": "https://en.wikipedia.org/wiki/Investigational_New_Drug", "label": "Investigational New Drug application, overview"}]}, "evidence": {"kind": "spotFake", "prompt": "One of these is false. Tap it.", "statements": ["Verve kept testing in New Zealand and the UK.", "The FDA asked about off-target effects in other cells.", "The hold meant the FDA had rejected the drug for good."], "fakeIndex": 2, "explanation": "A hold is a request for answers. The US hold was lifted after nearly a year."}, "numbers": {"kind": "numberSense", "prompt": "Suppose a hold lasts 11 months and the company spends $10 million a month. What does it cost, in millions?", "min": 0, "max": 300, "value": 110, "unit": "M", "explanation": "$110 million of cash spent while the US trial waits. Holds are expensive."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're on the regulatory team that receives a hold letter like Verve's.", "prompt": "What goes into your response?", "options": ["An argument that the questions are unfair", "A promise to fix things after the trial", "New data on each question the FDA raised"], "correctIndex": 2, "consequences": ["Arguing does not replace the data the FDA asked for.", "The FDA wants answers before dosing, not after.", "Data that answers each point is what lifts a hold."], "explanation": "Holds lift when the FDA gets the data it asked for."}, "proReasoning": "Regulatory teams map every question in the letter to a study or analysis. Nothing is left unanswered.", "commonMistake": "Responding with arguments instead of data.", "mentalModel": "One question, one answer, with data."}, "invest": {"call": {"kind": "theCall", "situation": "A biotech's US IND is on hold, but its trial continues in other countries.", "prompt": "How do you weigh it?", "options": ["A delay to US plans, not a dead program", "A clear sign that the drug has failed", "No real effect at all on the company"], "correctIndex": 0, "consequences": ["Verve's hold lasted nearly a year, then lifted.", "A hold asks questions; it does not judge the drug.", "A year of US delay burns real cash."], "explanation": "A hold costs time and cash. It is not a failure, and it is not free."}, "proReasoning": "Investors model a hold as delay plus extra spending. Testing abroad can keep data coming.", "commonMistake": "Treating a hold as either fatal or harmless.", "mentalModel": "A hold costs time and cash."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup gets a hold letter with three questions. Cash is tight.", "prompt": "What's the priority?", "options": ["Start the US trial anyway", "Fund the studies that answer the letter", "Spend on marketing to calm investors"], "correctIndex": 1, "consequences": ["Dosing during a hold is not allowed.", "Answering the FDA is the only way the trial restarts.", "Investors calm down when the hold lifts."], "explanation": "Every dollar should go toward the answers that lift the hold."}, "proReasoning": "Founders under a hold cut everything that does not answer the letter. Speed to answers is speed to restart.", "commonMistake": "Spreading scarce cash across things the FDA did not ask for.", "mentalModel": "Spend on the answers."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks if a clinical hold means the drug is dangerous.", "prompt": "What's the best answer?", "options": ["Yes, it means it is proven harmful", "No, holds are just routine paperwork", "It means the FDA wants answers first"], "correctIndex": 2, "consequences": ["A hold asks questions; it proves nothing.", "Holds stop trials and can last a year.", "Verve had to answer questions before US trials resumed."], "explanation": "A hold pauses a trial until the FDA is satisfied about specific risks."}, "proReasoning": "A hold is caution, not a verdict. The FDA asks first and decides after.", "commonMistake": "Equating a hold with proven harm.", "mentalModel": "Caution, not a verdict."}}}$ml$::jsonb, ARRAY['handwritten-v1']::text[]),
($ml$c9d16113-619c-5cab-b701-96dd6f1f874a$ml$::uuid, $ml$biotech$ml$, 12, 1, $ml${"id": "biotech-d12-c1", "title": "Four species, no warning", "lessonTitle": "When animal tests missed the danger", "slot": 1, "type": "apply", "brief": {"headline": "In January 2016, a first-in-human trial in Rennes, France, left one healthy volunteer dead and five hospitalized. Animal studies in four species at high doses had shown nothing comparable.", "kicker": "Apply the TGN1412 lesson to a trial ten years later.", "fullText": "The drug was BIA 10-2474, a FAAH inhibitor from the Portuguese company Bial, meant as a painkiller. The contract research organization Biotrial ran the trial. Animal toxicology studies had been done in four species, at high doses and over long periods, to international standards. A French expert committee found no lesions or patterns in them that would have predicted the neurological harm seen in Rennes. Animal doses had been up to 650 times the dose absorbed by the hospitalized volunteers.\n\nThe committee recommended showing a drug's activity before human dosing, screening volunteers more carefully for drugs acting on the nervous system, and justifying the highest doses against the dose expected to work. Questions about exactly what happened remained open.\n\nLike TGN1412 in 2006, it showed that animal safety data is a guide, not a guarantee.", "sources": [{"url": "https://www.raps.org/resource/fda-toxicity-seen-in-fatal-french-study-does-not.html", "label": "RAPS, FDA says toxicity seen in fatal French study does not extend to its class, Aug 2016"}, {"url": "https://pharmafile.com/features/learning-northwick-park/", "label": "Pharmafile, Learning from Northwick Park, Feb 2007"}]}, "evidence": {"kind": "multipleChoice", "prompt": "Animals got up to 650 times the volunteers' dose without comparable harm. What does that show?", "options": ["The volunteers took the wrong drug", "Animal data can miss effects in humans", "The animal studies were skipped"], "correctIndex": 1, "explanation": "The studies were done to standard and still missed it. Some effects appear only in people."}, "numbers": {"kind": "numberSense", "prompt": "Animal doses were up to how many times the dose absorbed by the hospitalized volunteers?", "min": 0, "max": 1000, "value": 650, "unit": "x", "explanation": "Up to 650 times, with nothing comparable seen in four species."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're planning a first-in-human study of a drug that acts on the brain, after Rennes.", "prompt": "Which recommendation do you adopt?", "options": ["Start at the highest dose animals tolerated", "Screen volunteers with brain function tests", "Rely on the animal data alone"], "correctIndex": 1, "consequences": ["The committee urged justifying top doses against the dose expected to work.", "The committee urged neuropsychological screening for such drugs.", "Rennes showed animal data can miss human harm."], "explanation": "After Rennes, experts called for better volunteer screening and careful dose limits."}, "proReasoning": "Clinical pharmacologists build the lessons of past disasters into new protocols. Naming them shows judgment.", "commonMistake": "Treating clean animal data as permission to skip extra safeguards.", "mentalModel": "Learn from the last disaster."}, "invest": {"call": {"kind": "theCall", "situation": "A biotech's first human trial is about to start. Its animal data look clean.", "prompt": "How much comfort should that give?", "options": ["Complete, since clean data means safe", "None, since animal data is useless", "Some, but early human risk remains"], "correctIndex": 2, "consequences": ["Clean animal data still missed the Rennes effects.", "Animal data still guides the first doses.", "Four clean species did not prevent the Rennes harm."], "explanation": "Animal data lowers risk but cannot remove it. First human doses carry their own uncertainty."}, "proReasoning": "Investors treat first-in-human trials as a distinct risk, even with clean animal packages.", "commonMistake": "Treating clean animal data as a safety guarantee.", "mentalModel": "A guide, not a guarantee."}, "build_startup": {"call": {"kind": "theCall", "situation": "You're building tools that predict human toxicity.", "prompt": "Which gap does Rennes highlight?", "options": ["Human effects four species missed", "Paperwork errors at the trial site", "Too few animal species tested"], "correctIndex": 0, "consequences": ["That is the gap a better human model would target.", "The committee focused on the drug and the doses.", "Four species were tested and still missed it."], "explanation": "The studies were thorough and still missed the harm. Predicting human-only effects is the open problem."}, "proReasoning": "Founders target the failures that thorough work still misses. That is where a new tool adds value.", "commonMistake": "Blaming sloppiness when the method itself has limits.", "mentalModel": "Build for what good work still misses."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks how a drug tested on animals can still hurt people.", "prompt": "What's the best answer?", "options": ["Volunteers take far bigger doses", "Some effects show up only in humans", "Animal tests are usually faked"], "correctIndex": 1, "consequences": ["Animal doses were up to 650 times the volunteers'.", "Animals got far higher doses with no comparable harm.", "The Rennes studies met international standards."], "explanation": "Animals and humans differ. Some harms only appear when people take the drug."}, "proReasoning": "Animal tests filter out many dangers but not all. First human trials stay cautious for that reason.", "commonMistake": "Assuming harm in a trial means someone cheated.", "mentalModel": "Animals filter, not guarantee."}}}$ml$::jsonb, ARRAY['handwritten-v1']::text[]),
($ml$8f733b0b-054f-51a0-ae99-210f0c87be38$ml$::uuid, $ml$biotech$ml$, 12, 2, $ml${"id": "biotech-d12-c2", "title": "Safe enough to try is not safe", "lessonTitle": "When animal tests missed the danger", "slot": 2, "type": "connect", "brief": {"headline": "An IND's animal studies must show a drug is reasonably safe for first human testing. TGN1412's did, yet in 2006 all six men who received it became gravely ill.", "kicker": "Connect day 7 and day 12: what animal safety data can and cannot show.", "fullText": "On day 7 you saw the first part of an IND: animal pharmacology and toxicology studies showing whether a drug is reasonably safe for first human testing.\n\nOn day 12 you saw its limit. On March 13, 2006, six healthy men in London received TGN1412 at 0.1 mg per kg, a dose 500 times lower than the no-effect level in monkey studies. All six developed a cytokine storm, and at least four had multiple organ dysfunction. The UK regulator found no faults in the preclinical work and blamed an unpredicted biological action in humans.", "sources": [{"url": "https://en.wikipedia.org/wiki/Investigational_New_Drug", "label": "Investigational New Drug application, overview"}, {"url": "https://pharmafile.com/features/learning-northwick-park/", "label": "Pharmafile, Learning from Northwick Park, Feb 2007"}, {"url": "https://www.chemeurope.com/en/encyclopedia/TGN1412.html", "label": "TGN1412, encyclopedia entry"}]}, "evidence": {"kind": "buildChain", "prompt": "Follow TGN1412 from the lab to the ward.", "steps": ["Monkey studies set a no-effect level", "The trial starts at Northwick Park", "Six men get a dose 500 times lower", "All six develop a cytokine storm", "The regulator finds no fault in the animal work"], "explanation": "The animal work was sound. The drug still acted in humans in a way no one predicted."}, "numbers": {"kind": "numberSense", "prompt": "Of the six men who got TGN1412, at least how many had multiple organ dysfunction?", "min": 0, "max": 10, "value": 4, "unit": "men", "explanation": "At least four of six, from a dose 500 times below the monkey no-effect level."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You review an IND's toxicology section for a first-in-class immune drug.", "prompt": "What's the right stance?", "options": ["Trust clean animal data completely", "Reject any drug that acts on immunity", "Plan close monitoring even with clean data"], "correctIndex": 2, "consequences": ["Clean monkey data did not predict the cytokine storm.", "Many immune drugs are safe; caution is the lesson.", "TGN1412's preclinical work had no faults, yet harm followed."], "explanation": "Animal data clears a drug to be tried, carefully. It does not prove it safe in people."}, "proReasoning": "Reviewers separate \"safe enough to try\" from \"safe.\" The first justifies a careful trial, not a careless one.", "commonMistake": "Reading \"safe enough to try\" as \"safe.\"", "mentalModel": "Cleared to try, carefully."}, "invest": {"call": {"kind": "theCall", "situation": "TeGenero entered insolvency proceedings later in 2006, after TGN1412.", "prompt": "What's the lesson for valuing early biotechs?", "options": ["One first-trial disaster can end a company", "Clean animal data removes trial risk", "Every failed trial ends in insolvency"], "correctIndex": 0, "consequences": ["A single-drug company has nothing to fall back on.", "TGN1412's clean animal data did not prevent harm.", "Most failed trials do not sink a company."], "explanation": "Early biotechs often rest on one drug. A first-trial disaster can wipe them out."}, "proReasoning": "Investors size early positions knowing a first human trial can end a company. Clean preclinical data does not change that.", "commonMistake": "Treating the IND safety package as the end of safety risk.", "mentalModel": "First trials can end companies."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup's lead drug acts on the immune system. Its animal data look clean.", "prompt": "What first-dose plan fits?", "options": ["Dose a large group to save time", "Start low and watch each person closely", "Start high to show effect quickly"], "correctIndex": 1, "consequences": ["More people at once means more people at risk.", "First human doses start low because animals can miss human effects.", "TGN1412 harmed people at a dose 500 times below the monkeys'."], "explanation": "Animals are not small humans. First doses start low and are watched closely."}, "proReasoning": "Founders who plan cautious first doses protect patients and the company. Speed here is false economy.", "commonMistake": "Rushing a first-in-human trial to save months.", "mentalModel": "Start low, watch closely."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why first doses in trials are so tiny.", "prompt": "What's the reason?", "options": ["The drugs are too expensive to make", "Regulators like small numbers", "Animals can miss effects that hit humans"], "correctIndex": 2, "consequences": ["Cost is not why first doses are small.", "Small first doses protect people from the unknown.", "TGN1412 harmed six men at a dose 500 times below the monkeys'."], "explanation": "Animal data is only a guide. Small first doses limit harm if humans react differently."}, "proReasoning": "Caution at the first dose comes from hard lessons. TGN1412 is the one every trial designer knows.", "commonMistake": "Thinking small doses mean the drug is weak.", "mentalModel": "Small first steps into the unknown."}}}$ml$::jsonb, ARRAY['handwritten-v1']::text[]),
($ml$a947b64d-4fea-560c-88a3-6ee38423285f$ml$::uuid, $ml$biotech$ml$, 12, 3, $ml${"id": "biotech-d12-c3", "title": "Planning the first dose", "lessonTitle": "When animal tests missed the danger", "slot": 3, "type": "decide", "brief": {"headline": "TGN1412 was given at 0.1 mg per kg, 500 times below the monkey no-effect level. All six men who got it fell gravely ill, and the regulator blamed an unpredicted action in humans.", "kicker": "Decide what lowers first-dose risk and what only feels safe.", "fullText": "On March 13, 2006, eight healthy men joined a first-in-human trial of TGN1412 at Northwick Park Hospital in London. Six received the drug and two a placebo. All six developed a cytokine storm, and at least four suffered multiple organ dysfunction. The UK regulator found no faults in the preclinical work.\n\nTeGenero, the company behind it, entered insolvency proceedings later in 2006. A drug can look safe in animals and still harm people, which is why first human doses start low.\n\nYou run safety at a biotech about to start its first human trial.", "sources": [{"url": "https://pharmafile.com/features/learning-northwick-park/", "label": "Pharmafile, Learning from Northwick Park, Feb 2007"}, {"url": "https://www.chemeurope.com/en/encyclopedia/TGN1412.html", "label": "TGN1412, encyclopedia entry"}]}, "evidence": {"kind": "sortSignal", "prompt": "Does each choice lower first-dose risk or only feel safe?", "buckets": ["Lowers the risk", "Only feels safe"], "items": [{"text": "Starting far below the animal no-effect level", "bucket": 0}, {"text": "Watching each volunteer closely", "bucket": 0}, {"text": "Asking which human risks animals cannot show", "bucket": 0}, {"text": "Assuming monkeys predict humans exactly", "bucket": 1}, {"text": "Treating clean animal data as a guarantee", "bucket": 1}], "explanation": "Low doses, close watching and honest questions reduce risk. Faith in animal data does not."}, "numbers": {"kind": "numberSense", "prompt": "The dose was 0.1 mg per kg, 500 times below the monkeys' no-effect level. What was that level, in mg per kg?", "min": 0, "max": 120, "value": 50, "unit": "mg/kg", "explanation": "0.1 times 500 is 50 mg per kg. A wide margin, and it still was not enough."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "In an interview for a clinical safety role, you are asked how you would set a first human dose after TGN1412.", "prompt": "What's the strongest answer?", "options": ["Very low and closely watched", "Right at the animal no-effect level", "Whatever dose the sponsor prefers"], "correctIndex": 0, "consequences": ["That is the caution TGN1412 taught.", "TGN1412 harmed people at 500 times below that level.", "Dose choice rests on safety, not preference."], "explanation": "TGN1412 showed that even big safety margins from animals can fail."}, "proReasoning": "Have a view on first doses and ground it in TGN1412. Interviewers want to hear caution with reasons.", "commonMistake": "Treating the animal no-effect level as a safe human dose.", "mentalModel": "Margins from animals can fail."}, "invest": {"call": {"kind": "theCall", "situation": "You hold shares in a one-drug biotech. Its first human trial starts next month.", "prompt": "How should you treat the position?", "options": ["Ignore the trial; it is just Phase 1", "Size it knowing one trial could sink it", "Add more, since animal data was clean"], "correctIndex": 1, "consequences": ["A first trial can decide a one-drug company's fate.", "TeGenero entered insolvency after its first trial.", "TGN1412's animal data was clean too."], "explanation": "A first human trial is a real risk event for a single-drug company."}, "proReasoning": "Investors size positions in one-drug biotechs for binary outcomes. The first human trial is one.", "commonMistake": "Treating Phase 1 as routine for a company with one drug.", "mentalModel": "One drug, one big risk."}, "build_startup": {"call": {"kind": "theCall", "situation": "You are building a startup that helps safety teams spot human risks animals miss.", "prompt": "Who should you interview first?", "options": ["Marketing teams at big drugmakers", "Patients already taking approved drugs", "Safety teams, about risks they can't predict"], "correctIndex": 2, "consequences": ["Marketing teams do not set first doses.", "The gap is before approval, in first trials.", "They know where animal data leaves gaps."], "explanation": "The people who set first doses know where predictions fail. Start with them."}, "proReasoning": "Founders find the person who carries the risk and ask what they still cannot see.", "commonMistake": "Interviewing people far from the problem.", "mentalModel": "Ask who carries the risk."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks whether TGN1412 means animal testing is pointless.", "prompt": "What's the fairest answer?", "options": ["No, but it is a guide, not a guarantee", "Yes, animals tell us nothing", "No, it proves animal tests are perfect"], "correctIndex": 0, "consequences": ["Animal data still sets limits, but humans can differ.", "Animal studies still screen out many dangers.", "TGN1412 shows exactly where they fall short."], "explanation": "Animal tests help, but they cannot predict everything a drug does in people."}, "proReasoning": "Hold two ideas at once: animal data is useful, and it has limits. TGN1412 shows both.", "commonMistake": "Swinging from \"animal tests prove safety\" to \"they are useless.\"", "mentalModel": "Useful, and limited."}}}$ml$::jsonb, ARRAY['handwritten-v1']::text[])
